/* Flashcards — memorização ativa (recall + repetição espaçada) para o ENARE Farmácia. */
window.FLASHCARDS = [{"nome": "Cardiologia & orientação", "icone": "❤️", "cor": "#C0432F", "cards": [{"f": "Cite as classes de primeira linha no tratamento da HAS.", "v": "• <b>Diuréticos tiazídicos</b> (e similares: clortalidona, indapamida)<br>• <b>IECA</b><br>• <b>BRA</b><br>• <b>BCC di-hidropiridínicos</b> (anlodipino)<br>Macete <b>\"ABCD\"</b>: <b>A</b>=IECA/BRA, <b>B</b>=betabloqueador (só em indicações específicas), <b>C</b>=Cálcio (BCC), <b>D</b>=Diurético. Regra: nunca associar <b>IECA + BRA</b> (duplo bloqueio do SRAA aumenta LRA e hipercalemia).", "tag": "HAS"}, {"f": "Qual a diferença de mecanismo entre IECA e BRA — e por que só o IECA causa tosse?", "v": "<b>IECA</b>: bloqueia a ECA, reduz angiotensina II <b>e acumula bradicinina</b> (a ECA é a cininase II) → tosse seca e angioedema.<br><b>BRA</b>: bloqueia seletivamente o <b>receptor AT1</b>, sem mexer na bradicinina → sem tosse.<br>Macete: <b>\"pril tosse, sartana não\"</b>.", "tag": "HAS"}, {"f": "Qual o mecanismo dos diuréticos tiazídicos e quais distúrbios metabólicos eles causam?", "v": "Inibem o <b>cotransportador Na-Cl no túbulo contorcido distal</b>.<br>Macete dos <b>\"hipo/hiper\"</b>: <b>hipo</b>calemia, <b>hipo</b>natremia, <b>hipo</b>magnesemia | <b>hiper</b>uricemia (cuidado na gota), <b>hiper</b>glicemia, <b>hiper</b>lipidemia, <b>hiper</b>calcemia.<br>Diferença: a <b>alça (furosemida)</b> inibe o NKCC2 e <b>perde</b> cálcio; o tiazídico <b>retém</b> cálcio.", "tag": "HAS"}, {"f": "Como se define HAS resistente e qual o quarto fármaco de escolha?", "v": "PA <b>não controlada apesar de 3 anti-hipertensivos</b> em doses otimizadas, sendo <b>um deles um diurético</b> (idealmente tiazídico/clortalidona) — com adesão confirmada e pseudorresistência excluída (técnica de medida, avental branco, AINE, álcool).<br>4º fármaco: <b>espironolactona</b> (antagonista mineralocorticoide) — monitorar <b>K+ e creatinina</b>.", "tag": "HAS"}, {"f": "Quais os valores que definem hipertensão na MAPA e na MRPA?", "v": "<b>MAPA</b>: vigília ≥ <b>135/85</b> | sono ≥ <b>120/70</b> | média 24 h ≥ <b>130/80</b> mmHg.<br><b>MRPA</b> (automedida domiciliar): ≥ <b>130/80</b> mmHg.<br>Macete: fora do consultório o corte cai — <b>140/90 no consultório vira 135/85 acordado</b>. São esses exames que revelam a <b>HAS do avental branco</b> (alta só no consultório) e a <b>HAS mascarada</b> (normal no consultório, alta fora dele).", "tag": "HAS"}, {"f": "Qual a meta pressórica no consultório para o hipertenso tratado?", "v": "Meta mínima <b>< 140/90 mmHg</b> para todos; se bem tolerado, buscar <b>120–129 / 70–79 mmHg</b> na maioria dos adultos, inclusive <b>diabéticos, DRC e coronariopatas</b>.<br>• <b>Idoso frágil / muito idoso</b>: individualizar, aceitando alvos menos rígidos e vigiando <b>hipotensão postural e quedas</b><br>• Nunca reduzir a diastólica a ponto de causar sintomas (<b>≥ 70 mmHg</b> como piso prático).", "tag": "HAS"}, {"f": "Qual anti-hipertensivo priorizar em: DM com albuminúria, pós-IAM, gestante, gota e asma?", "v": "• DM com <b>albuminúria</b> → <b>IECA ou BRA</b> (nefroproteção)<br>• <b>Pós-IAM</b> → <b>betabloqueador + IECA/BRA</b><br>• <b>Gestante</b> → <b>metildopa, nifedipino de liberação lenta, labetalol/hidralazina</b> (IECA/BRA são <b>contraindicados</b>)<br>• <b>Gota</b> → evitar tiazídico (hiperuricemia)<br>• <b>Asma/DPOC broncoespástico</b> → evitar betabloqueador não seletivo", "tag": "HAS"}, {"f": "Quais são os 4 pilares do tratamento da IC com fração de ejeção reduzida?", "v": "• <b>INRA (sacubitril/valsartana) ou IECA/BRA</b><br>• <b>Betabloqueador</b><br>• <b>Antagonista mineralocorticoide</b> (espironolactona/eplerenona)<br>• <b>iSGLT2</b> (dapagliflozina/empagliflozina — benefício <b>independe de diabetes</b>)<br>Os <b>4 reduzem mortalidade</b> e devem ser iniciados precocemente, em doses baixas e simultâneas. Macete: <b>\"ABCD da IC\"</b> — <b>A</b>RNI, <b>B</b>etabloqueador, <b>C</b> (antagonista do mineralo<b>C</b>orticoide), <b>D</b>apagliflozina.", "tag": "IC"}, {"f": "Quais betabloqueadores têm evidência de redução de mortalidade na ICFEr?", "v": "Apenas <b>carvedilol</b>, <b>succinato de metoprolol</b> (liberação prolongada) e <b>bisoprolol</b> — nebivolol em idosos. <b>Não é efeito de classe</b>: tartarato de metoprolol, atenolol e propranolol <b>não</b> servem para essa indicação.<br>Macete: <b>\"Carvalho Bissexto do Metrô\"</b> → <b>Carve</b>dilol, <b>Bis</b>oprolol, <b>Meto</b>prolol succinato.", "tag": "IC"}, {"f": "Como se titula a terapia da IC e o que NÃO justifica suspender o fármaco?", "v": "Iniciar em <b>dose baixa</b> e dobrar a cada <b>2 semanas</b> até a <b>dose-alvo do estudo</b> ou a máxima tolerada — a maior parte do benefício depende de chegar à dose-alvo.<br><b>Não suspender</b> por: queda assintomática da PA, aumento de creatinina até ~30% do basal ou piora transitória de sintomas ao iniciar betabloqueador. Macete: <b>\"start low, go slow, but GO\"</b>.", "tag": "IC"}, {"f": "Qual o intervalo obrigatório ao trocar um IECA por sacubitril/valsartana e por quê?", "v": "<b>36 horas de washout</b> após a última dose do IECA. Motivo: a <b>neprilisina inibida</b> degrada bradicinina; somada ao IECA, o risco de <b>angioedema</b> dispara.<br>• <b>Nunca</b> associar INRA + IECA<br>• Contraindicado se <b>história de angioedema</b><br>• Da troca de <b>BRA</b> → não precisa de intervalo.", "tag": "IC"}, {"f": "Que exames monitorar após iniciar espironolactona na IC e quando suspender?", "v": "<b>Potássio e creatinina</b> em <b>1 a 2 semanas</b>, repetindo após cada ajuste e periodicamente.<br>• Suspender/reavaliar se <b>K+ > 5,5 mEq/L</b> ou piora relevante da função renal<br>• Não iniciar com K+ elevado ou TFG muito reduzida<br>• Efeito adverso típico: <b>ginecomastia</b> (menor com eplerenona).", "tag": "IC"}, {"f": "A digoxina reduz mortalidade na IC? Quais os cuidados farmacêuticos principais?", "v": "<b>Não reduz mortalidade</b> — reduz <b>hospitalizações</b> por IC e controla FC na FA.<br>• <b>Janela terapêutica estreita</b>: alvo na IC <b>0,5–0,9 ng/mL</b><br>• <b>Hipocalemia e hipomagnesemia potencializam a toxicidade</b><br>• Intoxicação: náusea, confusão, <b>xantopsia</b> (visão amarelada), arritmias<br>Macete: <b>\"K baixo = digoxina brava\"</b>.", "tag": "IC"}, {"f": "Cite fármacos que devem ser evitados no paciente com ICFEr.", "v": "• <b>AINEs/coxibes</b> (retenção de sódio, piora renal e da congestão)<br>• <b>Verapamil e diltiazem</b> (inotropismo negativo)<br>• <b>Glitazonas</b> (pioglitazona — retenção hídrica)<br>• <b>Antiarrítmicos classe I</b> e sotalol (pró-arritmia)<br>• Corticoides e descongestionantes simpatomiméticos<br>Macete: <b>\"AINE + glitazona + verapamil = internação\"</b>.", "tag": "IC"}, {"f": "Qual a duração padrão da dupla antiagregação plaquetária após uma síndrome coronariana aguda?", "v": "<b>AAS + inibidor de P2Y12 por 12 meses</b> (padrão), seguido de <b>AAS indefinidamente</b>.<br>• <b>Alto risco de sangramento</b> → encurtar a DAPT (1–3–6 meses) e manter monoterapia<br>• <b>Alto risco isquêmico e baixo de sangramento</b> → pode prolongar além de 12 meses<br>Macete: <b>\"12 meses é a régua; o sangramento encurta, a isquemia estica\"</b>.", "tag": "SCA"}, {"f": "Por que o clopidogrel pode falhar e qual IBP deve ser preferido junto com ele?", "v": "Clopidogrel é <b>pró-fármaco</b> que precisa ser ativado pelo <b>CYP2C19</b>. <b>Metabolizadores lentos</b> e inibidores do CYP2C19 (<b>omeprazol e esomeprazol</b>) reduzem sua ativação.<br>Preferir <b>pantoprazol</b> (mínima inibição do 2C19).<br>Macete: <b>\"clopidogrel odeia OMEprazol; PANtoprazol é o par\"</b>.", "tag": "SCA"}, {"f": "Cite 4 características do ticagrelor que o diferenciam do clopidogrel.", "v": "• <b>Não é pró-fármaco</b> (ação direta e mais rápida) e é <b>reversível</b><br>• Posologia <b>12/12 h</b> (clopidogrel é 1×/dia) — grande risco de erro de adesão<br>• Efeitos típicos: <b>dispneia</b> e pausas/bradiarritmia<br>• Exige <b>AAS de manutenção ≤ 100 mg/dia</b> (doses maiores reduzem seu benefício)<br>Macete: <b>\"Ticagrelor: 2 vezes ao dia, AAS baixinho e falta de ar\"</b>.", "tag": "SCA"}, {"f": "Quais as contraindicações e cautelas do prasugrel?", "v": "• <b>Contraindicado</b> em quem teve <b>AVC ou AIT prévio</b><br>• <b>Cautela/dose reduzida</b> se <b>idade ≥ 75 anos</b> ou <b>peso < 60 kg</b><br>• Uso essencialmente após <b>anatomia coronariana conhecida/ICP</b><br>Macete <b>\"3×75/60\"</b>: <b>AVC prévio, ≥75 anos, <60 kg</b> = pense duas vezes antes do prasugrel.", "tag": "SCA"}, {"f": "Cite as classes que devem compor a prescrição de alta após um infarto.", "v": "• <b>AAS</b> + <b>inibidor de P2Y12</b> (DAPT)<br>• <b>Estatina de alta intensidade</b><br>• <b>Betabloqueador</b><br>• <b>IECA/BRA</b> (sobretudo se FE reduzida, DM, HAS ou DRC)<br>• <b>Antagonista mineralocorticoide</b> se FE ≤ 40% com IC ou diabetes<br>Macete <b>\"BASE\"</b>: <b>B</b>etabloqueador, <b>A</b>ntiagregantes, <b>S</b>tatina (estatina), <b>E</b>nzima (IECA).", "tag": "SCA"}, {"f": "Quais os itens do escore CHA2DS2-VA e a partir de quanto se anticoagula?", "v": "<b>C</b> IC (1) • <b>H</b> hipertensão (1) • <b>A2</b> idade ≥ 75 (2) • <b>D</b> diabetes (1) • <b>S2</b> AVC/AIT/tromboembolismo prévio (2) • <b>V</b> doença vascular (1) • <b>A</b> idade 65–74 (1).<br>A versão atual da ESC <b>retirou o sexo feminino</b> (era o \"Sc\" do CHA2DS2-VASc). <b>Anticoagular se ≥ 2</b>; considerar se 1.<br>Macete: <b>só o A de idade ≥75 e o S de AVC valem 2 pontos</b>.", "tag": "FA"}, {"f": "O que significa um HAS-BLED ≥ 3 — e isso contraindica anticoagulação?", "v": "Indica <b>alto risco de sangramento</b>, mas <b>NÃO contraindica</b> anticoagular. Serve para <b>corrigir fatores modificáveis</b> e reforçar o seguimento: PAS > 160, INR lábil, <b>AINE/antiagregantes</b>, <b>álcool</b>, função hepática/renal.<br>Macete: <b>HAS-BLED não tira o anticoagulante; tira o AINE, a bebida e a PA alta</b>.", "tag": "FA"}, {"f": "Quando a varfarina é obrigatória na FA (não pode ser trocada por DOAC)?", "v": "Na <b>FA valvar</b>:<br>• <b>Prótese valvar mecânica</b><br>• <b>Estenose mitral moderada a grave</b> (reumática)<br>Nesses casos os DOACs são <b>contraindicados</b> (dabigatrana aumentou eventos em prótese mecânica). Alvo de <b>INR 2–3</b> (mais alto em algumas próteses).<br>Macete: <b>\"válvula mecânica e mitral apertada = varfarina\"</b>.", "tag": "FA"}, {"f": "Como a função renal altera a dose dos DOACs na fibrilação atrial?", "v": "• <b>Apixabana</b>: reduzir para 2,5 mg 12/12 h se <b>2 de 3</b>: idade ≥ 80 anos, peso ≤ 60 kg, creatinina ≥ 1,5 mg/dL<br>• <b>Rivaroxabana</b>: 20 mg/dia; <b>15 mg</b> se ClCr 15–50 mL/min<br>• <b>Dabigatrana</b>: a mais dependente do rim (~80% renal) — evitar em ClCr < 30<br>Macete: <b>apixabana é a mais \"amiga do rim\"; dabigatrana, a menos</b>. Usar <b>Cockcroft-Gault</b> para essas bulas.", "tag": "FA"}, {"f": "Qual o agente de reversão de cada anticoagulante oral?", "v": "• <b>Dabigatrana</b> → <b>idarucizumabe</b> (anticorpo específico)<br>• <b>Rivaroxabana/apixabana</b> (anti-Xa) → <b>andexanet alfa</b>; alternativa: <b>CCP de 4 fatores</b><br>• <b>Varfarina</b> → <b>vitamina K</b> + <b>CCP</b> (ou plasma se indisponível)<br>Macete: <b>\"IDArucizumabe para o DAbigatrana\"</b> (as letras se repetem).", "tag": "FA"}, {"f": "Quais orientações de administração são específicas de cada DOAC?", "v": "• <b>Rivaroxabana</b> 15/20 mg: <b>tomar com alimento</b> (aumenta a biodisponibilidade) e sempre no mesmo horário<br>• <b>Apixabana e dabigatrana</b>: <b>12/12 h</b>, com ou sem alimento<br>• <b>Dabigatrana</b>: <b>não abrir/triturar a cápsula</b> (aumenta muito a absorção) e manter na embalagem original — sensível à <b>umidade</b><br>Macete: <b>\"Rivaroxabana janta junto\"</b>.", "tag": "FA"}, {"f": "Quais são as estatinas de alta intensidade e o que define essa categoria?", "v": "Alta intensidade = redução de <b>LDL ≥ 50%</b>: <b>atorvastatina 40–80 mg</b> e <b>rosuvastatina 20–40 mg</b>.<br>Moderada (30–50%): atorvastatina 10–20, rosuvastatina 5–10, sinvastatina 20–40, pravastatina 40.<br>Mecanismo: inibem a <b>HMG-CoA redutase</b> → mais receptores hepáticos de LDL.<br>Macete: <b>só \"ATO e ROSA\" em dose alta são de alta intensidade</b>.", "tag": "Dislipidemia"}, {"f": "Cite as metas de LDL-colesterol por categoria de risco cardiovascular.", "v": "• <b>Muito alto risco</b> (doença aterosclerótica estabelecida): LDL <b>< 50 mg/dL</b> — diretrizes europeias adotam <b>< 55</b> e redução ≥ 50%<br>• <b>Alto risco</b>: < <b>70</b> mg/dL<br>• <b>Risco intermediário</b>: < <b>100</b> mg/dL<br>• <b>Baixo risco</b>: < <b>130</b> mg/dL<br>Macete da escada: <b>130 → 100 → 70 → 50</b>, conforme o risco sobe.", "tag": "Dislipidemia"}, {"f": "Qual o mecanismo da ezetimiba e quando associá-la?", "v": "Inibe a proteína <b>NPC1L1</b> na borda em escova do intestino → bloqueia a <b>absorção intestinal de colesterol</b> (biliar e dietético). Reduz LDL em ~15–25% adicionais.<br>Indicação: paciente que <b>não atinge a meta</b> com estatina de alta intensidade, ou <b>intolerante</b> a doses altas.<br>Macete: <b>\"eZetimiba = Zero absorção intestinal\"</b>.", "tag": "Dislipidemia"}, {"f": "Qual o mecanismo dos inibidores de PCSK9 e da inclisirana?", "v": "A <b>PCSK9</b> degrada o receptor hepático de LDL. Bloqueá-la <b>preserva os receptores</b> → mais captação de LDL (redução adicional ~50–60%).<br>• <b>Evolocumabe e alirocumabe</b>: anticorpos monoclonais <b>subcutâneos</b> (a cada 2–4 semanas)<br>• <b>Inclisirana</b>: <b>RNA de interferência</b>, aplicação semestral após as doses iniciais<br>Macete: <b>\"PCSK9 é a tesoura do receptor; o mAb prende a tesoura\"</b>.", "tag": "Dislipidemia"}, {"f": "Qual a conduta diante de mialgia em paciente usando estatina?", "v": "Avaliar sintomas + <b>CK</b> e excluir causas (exercício, hipotireoidismo, interações):<br>• <b>CK > 10× LSN</b> ou rabdomiólise/sintomas intensos → <b>suspender</b> a estatina e hidratar/investigar<br>• Sintomas leves com CK normal ou pouco elevada → suspender temporariamente e <b>reintroduzir</b> em dose menor, outra estatina ou em <b>dias alternados</b><br>Macete: <b>\"10 vezes = para; leve = troca ou reduz, não abandona\"</b>. Corrigir <b>hipotireoidismo</b> antes de culpar a estatina.", "tag": "Dislipidemia"}, {"f": "Cite interações relevantes das estatinas metabolizadas pelo CYP3A4.", "v": "<b>Sinvastatina, atorvastatina e lovastatina</b> usam o <b>CYP3A4</b> → risco de miopatia com <b>claritromicina, azóis (itraconazol), inibidores de protease, ciclosporina, amiodarona, verapamil/diltiazem, anlodipino</b> e <b>suco de toranja (grapefruit)</b>. A sinvastatina tem <b>limites de dose</b> obrigatórios com vários desses.<br>Alternativas mais seguras: <b>pravastatina e rosuvastatina</b> (pouco dependentes do 3A4).<br>Macete: <b>\"micina, azol e amiodarona não combinam com sinva\"</b>.", "tag": "Dislipidemia"}, {"f": "Paciente com tosse seca persistente após iniciar enalapril: qual o mecanismo e a conduta?", "v": "Acúmulo de <b>bradicinina e substância P</b> nas vias aéreas (efeito de classe, não dose-dependente; mais comum em mulheres, pode surgir semanas a meses depois).<br>Conduta: <b>substituir por um BRA</b> (losartana), que preserva a nefro/cardioproteção sem a tosse. <b>Não é alergia</b> e não se trata com antitussígeno.<br>Macete: <b>\"tosse do pril → troca pelo sartana\"</b>.", "tag": "Orientação"}, {"f": "O que orientar ao paciente que esqueceu uma dose do anti-hipertensivo ou do anticoagulante?", "v": "Regra geral: <b>tomar assim que lembrar</b>; se já estiver <b>perto do horário da próxima</b>, <b>pular</b> a esquecida. <b>Nunca dobrar a dose</b>.<br>• DOAC <b>1×/dia</b>: pular se faltarem menos de ~12 h<br>• DOAC <b>12/12 h</b>: pular se faltarem menos de ~6 h<br>• <b>Varfarina</b>: pode tomar no mesmo dia; se lembrar só no dia seguinte, pular e <b>anotar</b> para informar no controle do INR.", "tag": "Orientação"}, {"f": "Que orientações dar ao paciente com hipotensão postural em uso de anti-hipertensivos?", "v": "• <b>Levantar em duas etapas</b>: sentar na beira da cama, esperar 1–2 min antes de ficar de pé<br>• Evitar banho muito quente, álcool e jejum prolongado; hidratar-se<br>• Considerar <b>dose noturna</b> ou fracionamento (avaliar com o prescritor)<br>• Atenção especial a <b>idosos, doxazosina, diuréticos e nitratos</b>; sempre <b>medir a PA em pé</b><br>Macete: <b>\"conte até 30 antes de levantar\"</b>.", "tag": "Orientação"}, {"f": "Cite os pontos-chave da técnica correta de automedida da pressão arterial.", "v": "• <b>5 minutos de repouso</b>, sentado, <b>costas apoiadas</b>, <b>pés no chão</b>, pernas descruzadas<br>• Braço apoiado na <b>altura do coração</b>, <b>manguito do tamanho certo</b> sobre o braço nu<br>• Sem falar durante a medida; sem café, fumo ou exercício nos 30 min anteriores; <b>bexiga vazia</b><br>• <b>2 a 3 medidas</b> com 1 min de intervalo, manhã e noite, e <b>registrar em diário</b><br>• Usar aparelho <b>validado e de braço</b> (evitar os de punho).", "tag": "Orientação"}, {"f": "Que orientações dar sobre sal e potássio ao paciente cardiopata?", "v": "• Limitar o <b>sal a menos de 5 g/dia</b> (≈ 2 g de sódio); o maior vilão são os <b>industrializados/embutidos</b> — ensinar a ler o rótulo (sódio)<br>• <b>Substitutos de sal (\"sal light\") contêm cloreto de potássio</b>: risco de <b>hipercalemia</b> em quem usa <b>IECA/BRA, espironolactona</b> ou tem DRC<br>• Mesma cautela com suplementos de potássio e excesso de água de coco/banana nesse perfil.", "tag": "Orientação"}, {"f": "Por que os AINEs são um problema no paciente hipertenso e o que é a \"tripla ameaça\"?", "v": "AINEs inibem <b>prostaglandinas renais</b> → <b>retenção de sódio e água</b> e vasoconstrição: <b>elevam a PA</b> e antagonizam diuréticos, IECA/BRA e betabloqueadores.<br><b>Tripla ameaça (triple whammy)</b>: <b>IECA/BRA + diurético + AINE</b> → risco alto de <b>lesão renal aguda</b>.<br>Orientar: <b>preferir dipirona/paracetamol</b> e questionar sempre a automedicação com anti-inflamatórios.", "tag": "Orientação"}, {"f": "Qual o melhor horário para tomar diurético, sinvastatina e por que o anlodipino incha o tornozelo?", "v": "• <b>Diuréticos pela manhã</b> (segunda dose de furosemida até o meio da tarde) para não atrapalhar o sono<br>• <b>Sinvastatina à noite</b> (meia-vida curta; a síntese de colesterol é noturna); <b>atorvastatina e rosuvastatina</b> podem ser em qualquer horário<br>• <b>Anlodipino</b>: <b>edema maleolar dose-dependente</b> por vasodilatação arteriolar — <b>não</b> melhora com diurético; melhora reduzindo a dose ou <b>associando IECA/BRA</b>.", "tag": "Orientação"}, {"f": "Quais fatores explicam a baixa adesão em cardiologia e como o farmacêutico pode medi-la?", "v": "Doenças <b>assintomáticas</b> (HAS, dislipidemia), <b>polifarmácia</b>, efeitos adversos (tosse, edema, disfunção erétil), custo, crenças e regimes complexos.<br>Avaliação: <b>Morisky-Green (MMAS)</b>, contagem de comprimidos, registros de retirada na farmácia (<b>PDC/MPR</b>) e entrevista sem julgamento.<br>Macete das <b>5 dimensões da OMS</b>: <b>socioeconômica, sistema de saúde, doença, terapia e paciente</b>.", "tag": "Adesão"}, {"f": "Cite intervenções farmacêuticas eficazes para melhorar a adesão do paciente cardiopata.", "v": "• <b>Simplificar o regime</b>: combinações em <b>dose fixa/polipílula</b> e 1 tomada ao dia<br>• <b>Conciliação medicamentosa</b> e revisão da farmacoterapia (desprescrever duplicidades)<br>• Organizadores de dose, alarmes/lembretes e vínculo com rotina diária<br>• <b>Educação sobre o \"porquê\"</b>: PA e LDL controlados não dão sintoma<br>• Manejo ativo dos efeitos adversos (trocar IECA por BRA em vez de abandonar) e <b>seguimento telefônico</b> pós-alta.", "tag": "Adesão"}]}, {"nome": "Idoso, gestante & pediatria", "icone": "👶", "cor": "#B03A5B", "cards": [{"f": "No idoso, o que acontece com o Vd de fármacos LIPOSSOLÚVEIS e HIDROSSOLÚVEIS?", "v": "• <b>Lipossolúveis</b> (diazepam): ↑ gordura corporal → <b>↑ Vd e meia-vida prolongada</b> (acúmulo, sedação residual).<br>• <b>Hidrossolúveis</b> (digoxina, lítio, aminoglicosídeos): ↓ água corporal total → <b>↓ Vd e ↑ concentração</b> → menor dose de ataque.<br>• <b>↓ albumina</b> → ↑ fração livre de <b>varfarina e fenitoína</b> (toxicidade com nível TOTAL \"normal\").<br>• Macete: <b>gordura sobe → guarda o lipossolúvel; água desce → concentra o hidrossolúvel</b>.", "tag": "Idoso"}, {"f": "Quais benzodiazepínicos são preferidos no idoso quando o uso é inevitável — e por quê?", "v": "<b>Lorazepam, Oxazepam, Temazepam</b> — mnemônico <b>\"LOT\"</b>.<br>• Sofrem apenas <b>fase II (glicuronidação)</b>, mais preservada no idoso, e <b>não geram metabólitos ativos</b>.<br>• A <b>fase I (oxidação/CYP)</b> é a mais reduzida com a idade.", "tag": "Idoso"}, {"f": "Por que a creatinina sérica \"normal\" engana no idoso?", "v": "A ↓ da <b>massa muscular</b> reduz a produção de creatinina, <b>mascarando a perda de função renal</b>.<br>• Creatinina normal <b>não</b> significa TFG normal.<br>• Estimar a TFG por <b>CKD-EPI 2021</b> e ajustar fármacos de eliminação renal.", "tag": "Idoso"}, {"f": "Cite 2 alterações FARMACODINÂMICAS típicas do envelhecimento.", "v": "• <b>↑ sensibilidade do SNC</b> a benzodiazepínicos, opioides e anticolinérgicos (sedação, delirium).<br>• <b>↓ resposta beta-adrenérgica</b> (menor efeito de beta-agonistas e beta-bloqueadores).<br>• <b>↓ barorreflexo</b> → hipotensão ortostática e quedas.", "tag": "Idoso"}, {"f": "O que é CASCATA IATROGÊNICA (cascata de prescrição)? Dê 2 exemplos clássicos.", "v": "Uma <b>RAM é interpretada como nova doença</b> e tratada com outro fármaco.<br>• Metoclopramida → parkinsonismo → <b>levodopa</b>.<br>• Anlodipino → edema de MMII → <b>furosemida</b>.<br>• AINE → ↑ PA → anti-hipertensivo; anticolinesterásico → incontinência → <b>oxibutinina</b>.", "tag": "Idoso"}, {"f": "O que são os critérios de BEERS e a que população se aplicam?", "v": "Lista <b>explícita</b> da <b>AGS</b> de <b>medicamentos potencialmente inapropriados</b> em <b>idosos (≥65 anos)</b>.<br>• Domínios: evitar sempre; evitar em certas doenças; usar com cautela; interações a evitar; <b>ajuste pela função renal</b>.", "tag": "Idoso"}, {"f": "Qual a diferença entre STOPP e START?", "v": "• <b>STOPP</b> = medicamentos a <b>parar</b> (inapropriados, duplicidades, sem indicação).<br>• <b>START</b> = tratamentos <b>omitidos</b> que devem ser <b>iniciados</b> (ex.: estatina/IECA na indicação, cálcio + vitamina D na osteoporose).<br>• Macete: <b>STOP = pare / START = comece</b> — enxerga o excesso E a falta.", "tag": "Idoso"}, {"f": "Por que benzodiazepínicos são \"evitar em qualquer dose\" no idoso (Beers)?", "v": "<b>Sedação, declínio cognitivo, delirium, quedas e fraturas</b>, além de acidentes.<br>• A retirada deve ser <b>gradual (desmame)</b> pelo risco de abstinência e convulsão.<br>• Mesma lógica para os <b>\"Z-drugs\"</b> (zolpidem).", "tag": "Idoso"}, {"f": "Mnemônico da síndrome ANTICOLINÉRGICA e 3 fármacos de alta carga anticolinérgica.", "v": "<b>\"Seco como osso, vermelho como beterraba, quente como brasa, cego como morcego, louco como um chapeleiro\"</b> (boca seca, rubor, hipertermia, visão borrada, delirium) + <b>retenção urinária e constipação</b>.<br>• <b>Difenidramina, amitriptilina, oxibutinina</b> (também hidroxizina e escopolamina).", "tag": "Idoso"}, {"f": "Por que evitar AINEs no idoso? Que combinação renal é proibida?", "v": "<b>Hemorragia digestiva</b>, <b>lesão renal aguda</b>, retenção hídrica/descompensação de IC e <b>↑ da PA</b>.<br>• <b>\"Tríplice ameaça\" (triple whammy)</b>: <b>IECA/BRA + diurético + AINE</b> → risco alto de IRA.<br>• Com varfarina, ↑ importante do risco de sangramento.", "tag": "Idoso"}, {"f": "Qual o alerta de segurança dos ANTIPSICÓTICOS em idosos com demência?", "v": "<b>Aumento da mortalidade</b> (eventos cardio/cerebrovasculares e pneumonia) — <b>tarja preta</b>.<br>• Primeiro, <b>medidas não farmacológicas</b>; não usar para sintomas leves.<br>• Se inevitável: <b>menor dose, menor tempo</b>, com reavaliação periódica.", "tag": "Idoso"}, {"f": "Por que evitar GLIBENCLAMIDA (e clorpropamida) e MEPERIDINA no idoso?", "v": "• <b>Sulfonilureias de longa ação</b>: <b>hipoglicemia grave e prolongada</b>, agravada pela queda da função renal.<br>• <b>Meperidina</b>: acúmulo do metabólito <b>normeperidina</b> → <b>neurotoxicidade e convulsão</b>, com analgesia oral pobre.", "tag": "Idoso"}, {"f": "Defina POLIFARMÁCIA e DESPRESCRIÇÃO, com as etapas do processo.", "v": "• <b>Polifarmácia</b>: uso de <b>5 ou mais medicamentos</b> simultâneos.<br>• <b>Desprescrição</b>: retirada <b>planejada e supervisionada</b> de fármaco inapropriado.<br>• Etapas: listar <b>tudo</b> (inclusive isentos e fitoterápicos) → identificar alvos (risco > benefício, cascata) → <b>priorizar</b> → retirar <b>um por vez</b> com desmame → <b>monitorar</b>.", "tag": "Idoso"}, {"f": "O que são FRIDs? Cite as principais classes.", "v": "<b>Fall-Risk-Increasing Drugs</b> — fármacos que aumentam o risco de <b>queda</b>.<br>• <b>Benzodiazepínicos/Z-drugs, antipsicóticos, antidepressivos, opioides, anticonvulsivantes, anticolinérgicos</b>.<br>• <b>Anti-hipertensivos e diuréticos</b> (hipotensão ortostática) e <b>hipoglicemiantes</b> (hipoglicemia).", "tag": "Idoso"}, {"f": "Como o ↑ do volume plasmático e da TFG na gestação altera as doses?", "v": "• Volume plasmático sobe cerca de <b>40–50%</b> → <b>↑ Vd</b> e diluição; ↓ albumina → ↑ fração livre.<br>• <b>TFG ↑ ~50%</b> → maior depuração de fármacos renais (<b>lítio, betalactâmicos, digoxina</b>), podendo exigir <b>↑ de dose e monitoramento</b>.<br>• Esvaziamento gástrico e motilidade reduzidos retardam o pico oral.", "tag": "Gestante"}, {"f": "TALIDOMIDA: malformação característica, janela crítica e a regra do \"tudo ou nada\".", "v": "<b>Focomelia</b> / defeitos de redução de membros (também orelha, coração, TGI); janela ~<b>20 a 36 dias pós-concepção</b>.<br>• Maior risco teratogênico geral: <b>organogênese, 3ª a 8ª semana pós-concepção</b>.<br>• Nas <b>2 primeiras semanas</b> vale o <b>\"tudo ou nada\"</b>: perda do embrião ou reparo completo.", "tag": "Gestante"}, {"f": "ISOTRETINOÍNA na gestação: risco e exigências de segurança.", "v": "<b>Teratógeno maior</b> — defeitos <b>craniofaciais, de SNC, cardíacos e tímicos</b>, além de abortamento.<br>• Exige <b>teste de gravidez negativo</b> e <b>2 métodos contraceptivos</b>, mantidos por <b>1 mês após</b> o término.<br>• Atenção: a <b>acitretina</b> exige contracepção por anos após a suspensão.", "tag": "Gestante"}, {"f": "VARFARINA na gestação: o que causa e qual a alternativa?", "v": "<b>Embriopatia varfarínica</b> (hipoplasia nasal, condrodisplasia punctata), sobretudo entre <b>6 e 12 semanas</b>; no 3º trimestre, <b>hemorragia fetal/neonatal</b>.<br>• Trocar por <b>heparina (HBPM)</b>, que <b>não atravessa a placenta</b>.<br>• Na <b>amamentação</b> a varfarina é <b>compatível</b>.", "tag": "Gestante"}, {"f": "IECA e BRA na gestação: qual o quadro fetal clássico?", "v": "<b>Fetopatia</b> de 2º/3º trimestre: <b>oligoâmnio</b>, <b>disgenesia tubular renal</b>/insuficiência renal, <b>hipoplasia pulmonar</b>, contraturas de membros e <b>hipoplasia da calota craniana</b>.<br>• Suspender assim que a gestação for confirmada e trocar por anti-hipertensivo seguro.", "tag": "Gestante"}, {"f": "VALPROATO e METOTREXATO: por que são proibidos na gestação?", "v": "• <b>Valproato</b>: maior risco de <b>defeito de fechamento do tubo neural</b>, dismorfismo facial e <b>prejuízo neurocognitivo</b> — o pior antiepiléptico na gestação.<br>• <b>Metotrexato</b>: <b>antagonista do folato</b>, abortivo e teratógeno (craniofacial, membros, SNC).<br>• Macete: os dois <b>brigam com o folato / com o tubo neural</b>.", "tag": "Gestante"}, {"f": "TETRACICLINAS e AINEs: qual o risco e em que fase da gestação?", "v": "• <b>Tetraciclinas</b> (a partir do 2º trimestre): <b>manchamento dentário</b> e depósito ósseo por quelação do cálcio; hepatotoxicidade materna.<br>• <b>AINEs no 3º trimestre</b>: <b>fechamento precoce do ducto arterioso</b>, <b>oligoâmnio</b>/disfunção renal fetal e inibição do trabalho de parto.", "tag": "Gestante"}, {"f": "MISOPROSTOL no 1º trimestre com falha do abortamento: que malformações podem ocorrer?", "v": "<b>Sequência de Möbius</b> (paralisia dos nervos cranianos VI e VII) e <b>defeitos de redução de membros</b> — por <b>hipoperfusão</b> decorrente das contrações uterinas.<br>• Análogo da <b>PGE1</b>, abortivo, de dispensação controlada.", "tag": "Gestante"}, {"f": "Antimicrobianos SEGUROS na gestação e os que devem ser evitados.", "v": "• Seguros: <b>penicilinas, cefalosporinas, azitromicina, eritromicina (não estolato), fosfomicina</b>; nitrofurantoína útil na ITU, evitando o <b>termo</b>.<br>• Evitar: <b>tetraciclinas, quinolonas</b> e <b>sulfametoxazol-trimetoprima</b> (antifolato no 1º tri; risco de <b>kernicterus</b> perto do parto).", "tag": "Gestante"}, {"f": "Anti-hipertensivos de escolha na gestação (manutenção e crise).", "v": "• Manutenção: <b>metildopa</b>, <b>nifedipino</b> e <b>labetalol</b>.<br>• Crise/emergência hipertensiva: <b>hidralazina IV</b>, <b>nifedipino VO</b> ou <b>labetalol IV</b>.<br>• Proibidos: <b>IECA/BRA</b>; atenolol associado a restrição de crescimento fetal.", "tag": "Gestante"}, {"f": "Dose de ÁCIDO FÓLICO na gestação: padrão e alto risco.", "v": "• Padrão: <b>0,4 mg/dia (400 mcg)</b>, iniciando <b>pré-concepção</b> (ao menos 1 mês antes) até o fim do 1º trimestre.<br>• <b>4–5 mg/dia</b> no alto risco: <b>antecedente de defeito de tubo neural</b>, uso de <b>valproato/carbamazepina</b>, diabetes e obesidade.", "tag": "Gestante"}, {"f": "Tratamento de 1ª linha da náusea e vômito da gestação.", "v": "<b>Piridoxina (vitamina B6)</b>, isolada ou com <b>doxilamina</b>, somada a medidas dietéticas.<br>• Passos seguintes: <b>metoclopramida</b>, dimenidrinato/meclizina; ondansetrona nos casos refratários.<br>• Na <b>hiperêmese</b>: hidratação + <b>tiamina antes</b> do soro glicosado.", "tag": "Gestante"}, {"f": "Amamentação: fármacos COMPATÍVEIS, os que exigem suspensão e o macete de horário.", "v": "• Compatíveis: <b>paracetamol, ibuprofeno, penicilinas/cefalosporinas, heparina, varfarina, insulina, levotiroxina, metildopa, nifedipino</b>.<br>• Evitar: <b>amiodarona, antineoplásicos, radiofármacos, derivados do ergot</b>; <b>lítio</b> só com monitoramento estrito.<br>• <b>Codeína</b>: proibida — mãe <b>metabolizadora ultrarrápida do CYP2D6</b> gera excesso de morfina no leite → <b>depressão respiratória do lactente</b>.<br>• Menor exposição: <b>tomar logo APÓS a mamada</b>.", "tag": "Gestante"}, {"f": "Como o pH gástrico do recém-nascido altera a absorção oral?", "v": "O RN tem <b>hipocloridria relativa (pH mais alto)</b> → <b>↑ biodisponibilidade de fármacos ácido-lábeis</b> (penicilina G) e <b>↓ absorção de ácidos fracos</b> (fenobarbital, fenitoína).<br>• Esvaziamento gástrico <b>lento e irregular</b> retarda o pico; via <b>IM é errática</b> (baixa massa e perfusão).", "tag": "Pediatria"}, {"f": "Por que o neonato precisa de dose/kg MAIOR de aminoglicosídeo e intervalo MAIOR?", "v": "• <b>Maior água corporal total</b> (~75–80% no RN) → <b>↑ Vd</b> de hidrossolúveis → <b>dose/kg maior</b>.<br>• <b>Função renal imatura</b> (TFG ao nascer é fração da do adulto, amadurecendo nos primeiros meses) → <b>eliminação lenta</b>.<br>• Macete: <b>dose maior, intervalo maior</b>.", "tag": "Pediatria"}, {"f": "Por que sulfonamidas e ceftriaxona são perigosas no neonato?", "v": "<b>Deslocam a bilirrubina</b> da albumina (albumina baixa e de menor afinidade no RN) → <b>↑ bilirrubina livre</b> e risco de <b>kernicterus</b>.<br>• A ceftriaxona ainda é <b>incompatível com soluções de cálcio</b> no neonato (precipitação).", "tag": "Pediatria"}, {"f": "SÍNDROME DO BEBÊ CINZENTO: qual fármaco e qual o mecanismo?", "v": "<b>Cloranfenicol</b> — imaturidade da <b>glicuronil-transferase (fase II)</b> e da excreção renal → acúmulo tóxico.<br>• Quadro: <b>cianose acinzentada, vômitos, hipotermia e colapso cardiovascular</b>.<br>• Lição: o neonato <b>não</b> é um adulto em escala reduzida.", "tag": "Pediatria"}, {"f": "Por que a criança de 1 a 6 anos costuma precisar de dose/kg MAIOR que o adulto?", "v": "Depois da maturação enzimática, o <b>clearance por quilo</b> supera o do adulto (fígado e rim proporcionalmente maiores e muito ativos).<br>• Por isso as doses em <b>mg/kg/dia</b> nessa faixa parecem altas — mas <b>nunca ultrapassar a dose máxima do adulto</b>.", "tag": "Pediatria"}, {"f": "Qual a fórmula de MOSTELLER para superfície corporal e quando usá-la?", "v": "<b>SC (m²) = √[(altura em cm × peso em kg) ÷ 3600]</b>.<br>• Usada quando a dose é em <b>mg/m²</b>: <b>quimioterápicos</b>, alguns imunossupressores e antivirais.<br>• Fora desses casos, a dose pediátrica padrão é por <b>peso (mg/kg)</b>.", "tag": "Pediatria"}, {"f": "SÍNDROME DE REYE: qual fármaco, qual contexto e qual a exceção?", "v": "<b>AAS (salicilatos)</b> em criança/adolescente com <b>infecção viral</b> (influenza, varicela) → <b>encefalopatia aguda + esteatose hepática</b>.<br>• Antitérmico de escolha: <b>paracetamol</b> ou ibuprofeno.<br>• Exceção: uso terapêutico do AAS na <b>doença de Kawasaki</b> e em cardiopatias específicas.", "tag": "Pediatria"}, {"f": "TETRACICLINAS e FLUOROQUINOLONAS em pediatria: restrição e motivo.", "v": "• <b>Tetraciclinas: evitar em menores de 8 anos</b> — <b>manchamento dentário permanente</b> e depósito ósseo. Exceção aceita: <b>doxiciclina nas riquetsioses</b> (risco de vida).<br>• <b>Fluoroquinolonas</b>: <b>lesão de cartilagem/artropatia</b> em animais jovens e tendinopatia → uso restrito, sem alternativa.", "tag": "Pediatria"}, {"f": "Por que CODEÍNA e TRAMADOL são contraindicados em crianças?", "v": "Convertidos pelo <b>CYP2D6</b> em opioide ativo; o <b>metabolizador ultrarrápido</b> gera pico de morfina → <b>depressão respiratória e morte</b>.<br>• Contraindicados <b>abaixo de 12 anos</b> e, até os <b>18 anos</b>, após <b>amigdalectomia/adenoidectomia</b>.", "tag": "Pediatria"}, {"f": "PROMETAZINA em pediatria: qual a contraindicação absoluta?", "v": "<b>Menores de 2 anos</b> — risco de <b>depressão respiratória fatal</b>.<br>• Em qualquer idade pediátrica: sedação intensa e <b>reações distônicas/extrapiramidais</b>.<br>• Risco adicional de <b>lesão tecidual grave</b> se houver extravasamento ou injeção intra-arterial.", "tag": "Pediatria"}, {"f": "Quais EXCIPIENTES são problemáticos no neonato e que quadro causam?", "v": "• <b>Álcool benzílico / benzoato</b> → <b>\"gasping syndrome\"</b> (acidose metabólica, gasping, colapso).<br>• <b>Propilenoglicol</b> → hiperosmolaridade, acidose láctica e neurotoxicidade.<br>• <b>Etanol</b> em soluções orais; <b>sorbitol</b> → diarreia osmótica; <b>sacarose</b> → cárie no uso crônico.", "tag": "Pediatria"}, {"f": "Regras práticas de forma farmacêutica e administração em pediatria.", "v": "• <b>Seringa dosadora ou copo graduado</b>, <b>nunca colher de casa</b>; conferir a <b>mg/mL da apresentação</b> (gotas × solução oral têm concentrações diferentes → superdose).<br>• <b>Agitar suspensões</b> antes de cada dose.<br>• <b>Não triturar/abrir</b> liberação prolongada ou revestimento entérico; comprimido inteiro em geral só após ~<b>6 anos</b>.", "tag": "Pediatria"}, {"f": "Quais fatores mais comprometem a ADESÃO na criança — e como a farmácia clínica atua?", "v": "• <b>Palatabilidade</b>, volume grande, número de doses/dia e horários incompatíveis com a escola.<br>• Condutas: escolher sabor/forma aceita, <b>simplificar a posologia</b>, fornecer <b>dispositivo dosador</b> marcado, orientar <b>cuidador e criança</b> e usar calendário de doses.<br>• Não diluir a dose em mamadeira cheia — se sobrar leite, perde-se dose.", "tag": "Pediatria"}]}, {"nome": "Oncologia & terapia nutricional", "icone": "🧬", "cor": "#5B4A8A", "cards": [{"f": "Qual a diferença prática entre antineoplásico ciclo-celular ESPECÍFICO e INESPECÍFICO?", "v": "• <b>Específico (CCS):</b> só mata célula em fase definida (S, M) → resposta depende do <b>tempo de exposição</b> (infusão prolongada/fracionada).<br>• <b>Inespecífico (CCNS):</b> mata em qualquer fase, inclusive G0 → resposta <b>dose-dependente</b>.<br>Macete: <b>\"CCS = tempo; CCNS = dose\"</b>. Alquilantes e platinas = inespecíficos.", "tag": "Oncologia"}, {"f": "Mecanismo dos agentes ALQUILANTES e exemplos-chave.", "v": "Adicionam <b>radicais alquil ao N7 da guanina</b> → ligações cruzadas (cross-links) no DNA → replicação impedida. <b>Ciclo-celular inespecíficos</b>.<br>• Mostardas: ciclofosfamida, ifosfamida, melfalano, clorambucila<br>• Nitrosureias: carmustina/lomustina (atravessam a BHE)<br>• Outros: busulfano, dacarbazina, temozolomida<br>Risco tardio: <b>segunda neoplasia (LMA)</b> e infertilidade.", "tag": "Oncologia"}, {"f": "O que fazem os ANTIMETABÓLITOS e em que fase do ciclo agem?", "v": "São <b>análogos falsos</b> de folato/purina/pirimidina → bloqueiam a síntese de DNA na <b>fase S</b> (ciclo-específicos).<br>• Antifolato: <b>metotrexato</b> (inibe di-hidrofolato redutase)<br>• Pirimidinas: <b>5-FU, capecitabina, citarabina, gencitabina</b><br>• Purinas: mercaptopurina, fludarabina<br>Macete: <b>\"imitam o nutriente e travam a fábrica de DNA\"</b>.", "tag": "Oncologia"}, {"f": "Alcaloides da VINCA: mecanismo, fase e toxicidade limitante.", "v": "Ligam-se à <b>tubulina e INIBEM a polimerização</b> dos microtúbulos → fuso não se forma → parada em <b>metáfase (fase M)</b>.<br>• Vincristina: <b>neuropatia periférica</b> é a limitante (pouca mielotoxicidade)<br>• Vimblastina/vinorelbina: <b>mielossupressão</b> predomina<br>Macete: <b>\"vinCRIStina CRIS o nervo; vinBLAStina BLAsta a medula\"</b>.", "tag": "Oncologia"}, {"f": "TAXANOS: mecanismo, exemplos e cuidado obrigatório na infusão.", "v": "Fazem o <b>oposto da vinca</b>: <b>estabilizam</b> o microtúbulo e impedem a despolimerização → bloqueio em <b>M</b>. Ex.: paclitaxel, docetaxel.<br>• <b>Pré-medicação com corticoide + anti-H1/H2</b> (risco de reação de hipersensibilidade ao veículo Cremophor/polissorbato)<br>• Equipo <b>sem PVC + filtro em linha</b> (paclitaxel lixivia DEHP)<br>Macete: <b>\"Vinca desmonta, Taxano trava\"</b>.", "tag": "Oncologia"}, {"f": "ANTRACÍCLICOS: mecanismo e a toxicidade que define o teto de dose.", "v": "Intercalação no DNA + inibição da <b>topoisomerase II</b> + geração de <b>radicais livres</b> (complexo ferro-antraciclina).<br>• <b>Cardiotoxicidade crônica dose-dependente e cumulativa</b> (miocardiopatia dilatada, irreversível) — doxorrubicina limite acumulado da ordem de <b>450-550 mg/m²</b><br>• Exigem <b>ecocardiograma/FEVE antes e durante</b>; são vesicantes potentes.<br>Macete: <b>\"as -rubicinas ferem o coração\"</b>.", "tag": "Oncologia"}, {"f": "Para que serve o DEXRAZOXANO e por que ele funciona?", "v": "<b>Cardioprotetor</b> das antraciclinas: <b>quelante de ferro</b> — impede o complexo ferro-antraciclina e a geração de radicais livres no miócito (também atua na topoisomerase IIβ).<br>• Indicado em paciente que já acumulou dose alta (ex.: &gt;300 mg/m² de doxorrubicina) e segue com benefício clínico<br>• Também é <b>antídoto do extravasamento</b> de antraciclina (IV, começando em até 6 h).", "tag": "Oncologia"}, {"f": "Inibidores de TOPOISOMERASE I x II: quem é quem e a toxicidade marcante.", "v": "• <b>Topo I:</b> irinotecano e topotecano — <b>diarreia</b> é a marca. Precoce (colinérgica, &lt;24 h) → <b>atropina</b>; tardia (&gt;24 h) → <b>loperamida em dose alta</b>. Polimorfismo <b>UGT1A1</b> aumenta toxicidade.<br>• <b>Topo II:</b> etoposídeo, tenoposídeo (e as antraciclinas) — mielossupressão e risco de <b>LMA secundária</b>.<br>Macete: <b>\"topo I = intestino; topo II = medula\"</b>.", "tag": "Oncologia"}, {"f": "Platinas: mecanismo e o perfil de toxicidade que diferencia cisplatina, carboplatina e oxaliplatina.", "v": "Formam <b>ligações cruzadas no DNA</b> (comportam-se como alquilantes, ciclo-inespecíficos).<br>• <b>Cisplatina:</b> nefro, oto e neurotoxicidade + emese altíssima<br>• <b>Carboplatina:</b> <b>mielossupressão (plaquetopenia)</b>; dose por <b>AUC (fórmula de Calvert)</b>, não por m²<br>• <b>Oxaliplatina:</b> <b>neuropatia desencadeada pelo frio</b><br>Macete: <b>\"CIS rim, CARBO medula, OXALI frio\"</b>.", "tag": "Oncologia"}, {"f": "Como prevenir a nefrotoxicidade da CISPLATINA? E a ototoxicidade é reversível?", "v": "• <b>Hidratação vigorosa com salina 0,9% antes, durante e após</b> (garantir diurese; NaCl estabiliza a cisplatina), reposição de <b>magnésio e potássio</b>, evitar nefrotóxicos (AINE, aminoglicosídeo, contraste); diurético só com o paciente hidratado<br>• <b>Ototoxicidade:</b> perda de audição de alta frequência e zumbido — <b>cumulativa e geralmente IRREVERSÍVEL</b>; audiometria de base.<br>Macete: <b>\"cisplatina: hidrate ou perca o rim\"</b>.", "tag": "Oncologia"}, {"f": "Por que ciclofosfamida/ifosfamida causam cistite hemorrágica e como o MESNA evita?", "v": "Metabolizadas no fígado geram <b>ACROLEÍNA</b>, que se concentra na urina e agride o urotélio.<br>• <b>MESNA (2-mercaptoetanossulfonato)</b> é excretado na urina e o seu <b>grupo tiol (-SH) conjuga a acroleína</b>, inativando-a — <b>não interfere no efeito antitumoral</b><br>• Dose usual: ~<b>60% da dose da oxazafosforina</b>, fracionada (hora 0, +4 h, +8 h) + <b>hidratação e micção frequente</b>.<br>Macete: <b>\"MESNA = Mucosa da bexiga Salva\"</b>.", "tag": "Oncologia"}, {"f": "Metotrexato em altas doses: por que o resgate é com ÁCIDO FOLÍNICO e não ácido fólico?", "v": "O MTX inibe a <b>di-hidrofolato redutase</b>; o <b>ácido fólico precisaria dessa enzima</b> para ser reduzido — estaria bloqueado.<br>• O <b>ácido folínico (leucovorina/folinato de cálcio)</b> já é folato reduzido → entra direto na via e resgata a célula normal<br>• Iniciar em torno de <b>24 h após</b> o MTX, mantendo <b>hidratação + alcalinização urinária (pH &gt; 7)</b> e dosagem do nível sérico; toxicidade refratária → <b>glucarpidase</b>.<br>Macete: <b>\"folínico não precisa de enzima; fólico precisa\"</b>.", "tag": "Oncologia"}, {"f": "Terapia-alvo: o que os sufixos -MABE e -NIBE indicam e um exemplo com toxicidade típica?", "v": "• <b>-mabe = anticorpo monoclonal</b> (alvo extracelular/superfície): trastuzumabe (HER2) → <b>cardiotoxicidade geralmente REVERSÍVEL e não cumulativa</b>; rituximabe (CD20) → <b>reação infusional</b> e reativação de hepatite B<br>• <b>-nibe = inibidor de tirosinoquinase</b>, via oral, intracelular: imatinibe (BCR-ABL), erlotinibe (EGFR → <b>rash acneiforme</b>)<br>Macete: <b>\"maB = Bloqueia por fora; niB = inhiBe por dentro\"</b>.", "tag": "Oncologia"}, {"f": "O que é NADIR e por que ele importa para o farmacêutico?", "v": "É o <b>ponto mais baixo das contagens sanguíneas</b> após o ciclo — em geral entre o <b>7º e o 14º dia</b>, com recuperação até o 21º-28º (por isso o intervalo dos ciclos).<br>• Define o momento de <b>maior risco de neutropenia febril</b> (emergência oncológica → antibiótico em até 1 h)<br>• Orienta a <b>profilaxia com G-CSF</b> e o adiamento/ajuste de dose<br>Macete: <b>\"nadir = fundo do poço na 2ª semana\"</b>.", "tag": "Oncologia"}, {"f": "Mucosite quimioinduzida: fármacos clássicos e medidas de prevenção.", "v": "Clássicos: <b>metotrexato, 5-FU, citarabina, antraciclinas</b> (células de renovação rápida).<br>• <b>Higiene oral rigorosa</b>, escova macia, bochechos sem álcool<br>• <b>Crioterapia oral</b> (gelo durante o bolus de 5-FU) reduz incidência<br>• <b>Palifermina</b> em contexto de TCTH; analgesia escalonada<br>Macete: <b>\"boca e intestino sofrem junto — mucosite não é só oral\"</b>.", "tag": "Oncologia"}, {"f": "Síndrome MÃO-PÉ (eritrodisestesia palmoplantar): quais fármacos e o que orientar?", "v": "Clássicos: <b>capecitabina, 5-FU em infusão contínua, doxorrubicina lipossomal, sorafenibe/sunitinibe</b>.<br>• Eritema, disestesia, descamação e dor em palmas e plantas<br>• Orientar: <b>evitar calor, atrito, pressão e água quente</b>; hidratante emoliente (ureia), calçado macio<br>• Manejo: <b>interrupção temporária e redução de dose</b> — é toxicidade dose-dependente.", "tag": "Oncologia"}, {"f": "Compare a neuropatia da VINCRISTINA, do TAXANO e da OXALIPLATINA.", "v": "• <b>Vincristina:</b> motora e autonômica além da sensitiva → <b>íleo paralítico, constipação, pé caído</b>, perda do reflexo aquileu (profilaxia de constipação!)<br>• <b>Taxanos:</b> sensitiva distal \"em luva e bota\", dose-cumulativa<br>• <b>Oxaliplatina:</b> <b>aguda desencadeada pelo frio</b> (disestesia orofaríngea/laringoespasmo) — orientar a NÃO ingerir gelados nem tocar em objetos frios<br>Macete: <b>\"vinca prende o intestino, oxali odeia o frio\"</b>.", "tag": "Oncologia"}, {"f": "Por que a VINCRISTINA nunca pode ser administrada por via intratecal?", "v": "É <b>FATAL</b>: causa mielopatia/encefalopatia ascendente progressiva, sem antídoto eficaz — erro classificado como <b>never event</b>.<br>Barreiras obrigatórias:<br>• Diluir em <b>minibolsa (ex.: 50 mL)</b>, nunca em seringa<br>• Rótulo: <b>\"SOMENTE VIA INTRAVENOSA — FATAL SE ADMINISTRADA POR OUTRA VIA\"</b><br>• <b>Nunca dispensar junto</b> com medicamentos intratecais (separar tempo e local).<br>Macete: <b>\"vincristina: só na veia, nunca na coluna\"</b>.", "tag": "Oncologia"}, {"f": "Síndrome de LISE TUMORAL: quais alterações laboratoriais definem e qual eletrólito CAI?", "v": "Lise maciça libera o conteúdo intracelular: <b>↑ potássio, ↑ fósforo, ↑ ácido úrico</b> e, por quelação com o fosfato, <b>↓ CÁLCIO</b> → LRA, arritmia, convulsão.<br>• Risco: <b>linfoma de Burkitt, leucemias agudas, alta carga tumoral e alta quimiossensibilidade</b><br>• Base do manejo: <b>hidratação vigorosa</b> + monitorização; alcalinização não é mais rotina.<br>Macete: <b>\"sobe K, P e úrico; desce o Cálcio\"</b>.", "tag": "Oncologia"}, {"f": "ALOPURINOL x RASBURICASE na lise tumoral: quando usar cada um e qual a contraindicação absoluta?", "v": "• <b>Alopurinol:</b> inibe a xantina oxidase → <b>previne</b> a formação de ácido úrico (não reduz o já formado); usar em risco baixo/intermediário; ajustar mercaptopurina/azatioprina.<br>• <b>Rasburicase:</b> <b>urato oxidase</b> — converte o ácido úrico já existente em <b>alantoína</b> (solúvel) → risco alto ou hiperuricemia instalada.<br>• <b>Contraindicada na deficiência de G6PD</b> (hemólise/metemoglobinemia); coletar a amostra em <b>tubo gelado</b> para não subestimar o urato.", "tag": "Oncologia"}, {"f": "Como se classificam os esquemas quanto ao potencial EMETOGÊNICO?", "v": "Pela chance de êmese sem profilaxia:<br>• <b>Alto &gt; 90%:</b> cisplatina, AC (doxorrubicina + ciclofosfamida), dacarbazina, ciclofosfamida em dose alta<br>• <b>Moderado 30-90%:</b> carboplatina (AUC ≥ 4 é tratada como alto risco), oxaliplatina, irinotecano<br>• <b>Baixo 10-30%</b> e <b>Mínimo &lt; 10%</b> (ex.: bleomicina, vincristina, a maioria dos anticorpos monoclonais).<br>Macete: <b>\"CIA-D é alto: Cisplatina, Isofosfamida alta, AC, Dacarbazina\"</b>.", "tag": "Oncologia"}, {"f": "Profilaxia antiemética no esquema de ALTO risco e a diferença entre êmese aguda, tardia e antecipatória.", "v": "• <b>Alto risco:</b> associação de <b>antagonista NK1 + antagonista 5-HT3 + dexametasona (± olanzapina)</b> antes da infusão, mantendo dexametasona/NK1 nos dias seguintes<br>• <b>Aguda:</b> &lt; 24 h — mediada por <b>serotonina</b> (5-HT3 resolve)<br>• <b>Tardia:</b> 24-120 h — mediada por <b>substância P</b> (NK1 e dexametasona)<br>• <b>Antecipatória:</b> condicionamento antes do ciclo → <b>benzodiazepínico (lorazepam)</b> e boa profilaxia no 1º ciclo.<br>Macete: <b>\"aguda = serotonina; tardia = substância P; antecipatória = cabeça\"</b>.", "tag": "Oncologia"}, {"f": "Diferencie fármaco VESICANTE, IRRITANTE e não agressivo no extravasamento.", "v": "• <b>Vesicante:</b> causa <b>necrose e ulceração</b> ao extravasar — antraciclinas, alcaloides da vinca, mitomicina, mecloretamina<br>• <b>Irritante:</b> dor, flebite, eritema <b>sem necrose</b> — carboplatina, etoposídeo, oxaliplatina, ifosfamida<br>• <b>Não agressivo:</b> ciclofosfamida, metotrexato, citarabina<br>Macete: <b>\"vesicante VIRA FERIDA; irritante só ARDE\"</b>. Vesicante exige acesso confiável, de preferência <b>central</b>.", "tag": "Oncologia"}, {"f": "Conduta imediata no EXTRAVASAMENTO e os antídotos/compressas clássicos.", "v": "<b>Parar a infusão</b> mantendo o cateter → <b>aspirar</b> o resíduo → não lavar a linha → <b>demarcar e elevar</b> o membro → notificar e registrar.<br>• <b>Antraciclina:</b> compressa <b>FRIA</b> + <b>dexrazoxano IV</b> (ou DMSO tópico)<br>• <b>Alcaloides da vinca e etoposídeo:</b> compressa <b>MORNA</b> + <b>hialuronidase</b> (dispersar)<br>• <b>Mecloretamina:</b> <b>tiossulfato de sódio</b><br>Macete: <b>\"frio para quase tudo; calor para Vinca e Etoposídeo (V-E = Vai Esquentar)\"</b>.", "tag": "Oncologia"}, {"f": "Qual cabine é exigida para manipular antineoplásicos e por quê?", "v": "<b>Cabine de Segurança Biológica classe II tipo B2</b>: fluxo laminar <b>vertical</b>, filtro <b>HEPA</b> e <b>100% do ar exaurido para o exterior, SEM recirculação</b> → protege operador, produto e ambiente do aerossol citotóxico.<br>• Ligar e purgar antes de iniciar; <b>não obstruir as grelhas</b>; trabalhar na zona central da bancada<br>Contraste: <b>nutrição parenteral usa fluxo laminar HORIZONTAL</b> (protege só o produto) — jamais para citotóxico.", "tag": "Oncologia"}, {"f": "EPI e estrutura da sala de manipulação de antineoplásicos.", "v": "• <b>EPI:</b> avental de baixa permeabilidade, punho elástico, frente fechada; <b>luvas duplas de nitrila</b> (a de cima por fora do punho, troca periódica); <b>respirador PFF2/N95</b>, óculos, gorro e propés<br>• <b>Sala exclusiva com antecâmara e PRESSÃO NEGATIVA</b> em relação às áreas adjacentes (contém o contaminante)<br>• Uso de <b>sistema fechado, agulhas com filtro e técnica de pressão negativa no frasco</b> para evitar aerossol.<br>Macete: <b>\"citotóxico: pressão NEGATIVA; parenteral: pressão POSITIVA\"</b>.", "tag": "Oncologia"}, {"f": "Derramamento de citotóxico e descarte: conduta essencial.", "v": "• <b>Kit de derramamento</b> disponível: isolar e sinalizar a área, vestir EPI completo, <b>cobrir com material absorvente do centro para a periferia</b> (nunca varrer/secar a seco, não gerar aerossol), descontaminar, notificar e registrar<br>• <b>Descarte:</b> resíduo <b>Grupo B (quimioterápico)</b> em saco/recipiente rígido identificado com o símbolo de risco químico; perfurocortante contaminado vai no <b>Grupo E</b><br>• Excretas do paciente são consideradas contaminadas por <b>~48 h</b> (EPI ao manipular).", "tag": "Oncologia"}, {"f": "Quando indicar NUTRIÇÃO ENTERAL e quando a PARENTERAL é obrigatória?", "v": "Regra de ouro: <b>\"se o trato gastrintestinal funciona, USE-O\"</b>.<br>• <b>Enteral:</b> TGI funcionante mas ingestão oral insuficiente (&lt; 60% das necessidades) por 3-7 dias — mantém o trofismo da mucosa e reduz translocação bacteriana, é mais barata e mais fisiológica<br>• <b>Parenteral:</b> TGI <b>inacessível ou não funcionante</b> — obstrução intestinal, íleo prolongado, fístula de alto débito, isquemia mesentérica, síndrome do intestino curto grave, vômitos/diarreia incoercíveis.", "tag": "Terapia nutricional"}, {"f": "Vias de acesso da nutrição enteral: como escolher e qual o principal risco?", "v": "• <b>Curto prazo (&lt; 4-6 semanas):</b> sonda nasogástrica ou nasoentérica (pós-pilórica)<br>• <b>Longo prazo (&gt; 4-6 semanas):</b> <b>ostomias</b> — gastrostomia (GEP) ou jejunostomia<br>• <b>Pós-pilórica</b> quando há gastroparesia, alto resíduo ou risco elevado de aspiração<br>• Principal complicação: <b>broncoaspiração</b> → manter <b>cabeceira elevada 30-45°</b>; a diarreia costuma ser por velocidade de infusão, osmolaridade ou pelo <b>sorbitol dos medicamentos líquidos</b>, não pela dieta em si.", "tag": "Terapia nutricional"}, {"f": "Nutrição parenteral PERIFÉRICA x CENTRAL: o que decide a via?", "v": "A <b>OSMOLARIDADE</b> da formulação.<br>• <b>Periférica:</b> limite em torno de <b>900 mOsm/L</b> — acima disso há flebite química; uso curto (&lt; 7-14 dias), aporte limitado<br>• <b>Central:</b> osmolaridade alta, em veia de <b>alto fluxo (cava superior)</b> — permite NP total/prolongada; risco de infecção de corrente sanguínea associada a cateter<br>Macete: <b>\"acima de 900, só na CENTRAL\"</b>. A glicose é o principal determinante da osmolaridade.", "tag": "Terapia nutricional"}, {"f": "Macronutrientes na NP: quais os tetos de segurança que o farmacêutico checa?", "v": "• <b>Glicose:</b> velocidade de infusão até cerca de <b>4-5 mg/kg/min</b> (menos no crítico) — excesso causa <b>hiperglicemia, esteatose e ↑ CO2</b><br>• <b>Lipídeos:</b> em geral <b>≤ 1-1,5 g/kg/dia</b>, sem ultrapassar ~30% do VCT (limite 2,5 g/kg/dia) — evita síndrome de sobrecarga lipídica; fornecem ácidos graxos essenciais<br>• <b>Proteína:</b> ~<b>0,8-2,0 g/kg/dia</b> conforme catabolismo (não entra no cálculo do VCT nas fórmulas de calorias não proteicas).", "tag": "Terapia nutricional"}, {"f": "Incompatibilidade CÁLCIO-FOSFATO na NP: por que é grave e como preveni-la?", "v": "O fosfato de cálcio precipita → <b>micropartículas → embolia pulmonar e óbito</b> (é a incompatibilidade mais temida da NP).<br>Prevenção:<br>• Respeitar o <b>produto Ca × P</b> (limite usual &lt; 200 mg²/dL²)<br>• Usar <b>gluconato de cálcio</b> (dissocia menos que o cloreto)<br>• <b>Adicionar o FOSFATO no início e o CÁLCIO por último</b>, com agitação entre as adições<br>• <b>pH mais baixo, maior concentração de aminoácidos e temperatura baixa = mais solúvel</b>; calor favorece o precipitado.<br>Macete: <b>\"Fosfato primeiro, Cálcio por último\"</b>.", "tag": "Terapia nutricional"}, {"f": "O que compromete a ESTABILIDADE da emulsão lipídica (3 em 1) e como inspecioná-la?", "v": "Desestabilização = agregação → <b>coalescência → \"cracking\"</b> (separação de fase oleosa visível no topo, aspecto marmorizado) → risco de embolia.<br>Fatores: <b>pH baixo</b>, excesso de <b>cátions di/trivalentes (Ca²⁺, Mg²⁺, ferro)</b>, alta concentração de eletrólitos, baixa proporção de aminoácidos, temperatura e tempo excessivos.<br>• <b>Inspeção visual obrigatória</b> antes de liberar e antes de infundir; filtro <b>1,2 µm para 3 em 1</b> e <b>0,22 µm para 2 em 1</b>. Bolsa com quebra de fase = <b>descartar</b>.", "tag": "Terapia nutricional"}, {"f": "Quem tem risco de SÍNDROME DE REALIMENTAÇÃO?", "v": "Paciente <b>cronicamente depletado que recebe carga calórica (sobretudo glicose) rápida demais</b>:<br>• Jejum ou ingestão mínima por <b>&gt; 5-7 dias</b>, <b>IMC baixo</b>, perda de peso não intencional importante<br>• <b>Anorexia nervosa</b>, etilismo crônico, pós-bariátrica, oncológico caquético, idoso institucionalizado, greve de fome<br>• Eletrólitos já baixos <b>antes</b> de iniciar a terapia = risco máximo.<br>Macete: <b>\"quanto mais faminto, mais devagar\"</b>.", "tag": "Terapia nutricional"}, {"f": "Na síndrome de realimentação, o que CAI no sangue e o que se administra antes das calorias?", "v": "A insulina volta a subir e joga eletrólitos para dentro da célula: <b>↓ FÓSFORO (marcador principal), ↓ potássio, ↓ magnésio</b>, com retenção de sódio e água → arritmia, insuficiência cardíaca e respiratória, rabdomiólise, convulsão.<br>Conduta:<br>• <b>Tiamina (vitamina B1) ANTES ou junto</b> com a primeira oferta calórica (prevenir Wernicke)<br>• Iniciar com <b>10-20 kcal/kg/dia</b> e progredir devagar; repor eletrólitos e monitorar diariamente.<br>Macete: <b>\"cai FÓS-PO-MAG e falta B1\"</b>.", "tag": "Terapia nutricional"}, {"f": "Micronutrientes na NP: por que não podem ser esquecidos?", "v": "A NP é a <b>única fonte</b> de nutrientes — a ausência causa carência clínica rápida.<br>• <b>Vitaminas hidro e lipossolúveis diariamente</b> (as hidrossolúveis não são estocadas); <b>tiamina</b> é crítica<br>• <b>Oligoelementos:</b> zinco (cicatrização, perdas na diarreia/fístula), selênio, cobre, cromo, manganês<br>• Cuidados: <b>cobre e manganês reduzidos na colestase</b>; selênio e cromo ajustados na disfunção renal; vitaminas são <b>fotossensíveis</b> → proteger a bolsa da luz.", "tag": "Terapia nutricional"}, {"f": "FENITOÍNA por sonda com dieta enteral: qual o problema e a conduta?", "v": "A fórmula enteral <b>reduz drasticamente a absorção da fenitoína</b> (adsorção ao conteúdo/proteína e à sonda) → <b>níveis subterapêuticos e convulsão</b>.<br>Conduta:<br>• <b>Pausar a dieta 1-2 h antes e 1-2 h depois</b> da dose, lavando a sonda com água antes e após<br>• <b>Monitorar o nível sérico</b> e reavaliar a dose ao suspender/reintroduzir a dieta (risco inverso: intoxicação)<br>Macete: <b>\"fenitoína quer a sonda vazia\"</b>.", "tag": "Terapia nutricional"}, {"f": "Por que LEVOTIROXINA e CIPROFLOXACINO falham quando dados junto com a dieta enteral?", "v": "• <b>Levotiroxina:</b> a fórmula (e cálcio, ferro, soja, fibras) <b>reduz a absorção</b> → administrar em <b>jejum</b>, com pausa da dieta antes e depois, e lavar bem a sonda<br>• <b>Ciprofloxacino:</b> sofre <b>quelação com cátions divalentes/trivalentes (Ca²⁺, Mg²⁺, Fe²⁺, Zn²⁺)</b> da dieta e de antiácidos → queda importante da biodisponibilidade; pausar a dieta ~1-2 h antes e 2 h depois; a via <b>jejunal piora</b> a absorção<br>Macete: <b>\"quinolona + cálcio = quelato inútil\"</b>.", "tag": "Terapia nutricional"}, {"f": "Como administrar OMEPRAZOL por sonda e como manejar/prevenir a obstrução?", "v": "• Omeprazol tem <b>grânulos gastrorresistentes — NÃO triturar</b>: dispersar os grânulos em <b>bicarbonato de sódio 8,4%</b> (suspensão extemporânea) e infundir logo, lavando bem a sonda<br>• <b>Obstrução:</b> irrigar com <b>água morna em movimento suave de vai-e-vem com seringa de 20-60 mL</b>; <b>nunca usar refrigerante ou suco ácido</b> (coagula a proteína e piora) nem fio-guia<br>• <b>Prevenção:</b> lavar com 20-30 mL de água <b>antes e depois de cada medicamento</b>, um fármaco de cada vez, preferir formas líquidas e <b>nunca triturar liberação prolongada/entérica</b>.", "tag": "Terapia nutricional"}, {"f": "Papel do FARMACÊUTICO na terapia nutricional e na EMTN.", "v": "A legislação sanitária brasileira exige <b>EMTN multiprofissional</b> (médico, nutricionista, enfermeiro e <b>farmacêutico</b>) e atribui ao farmacêutico a responsabilidade técnica pela <b>NP</b>.<br>• <b>Avaliar a prescrição</b> (compatibilidade, estabilidade, osmolaridade, produto Ca × P, dose de eletrólitos)<br>• <b>Manipular</b> em <b>cabine de fluxo laminar horizontal ISO 5, em sala limpa com pressão positiva</b>, sob boas práticas<br>• Garantir <b>rotulagem, conservação (2-8 °C, ao abrigo da luz), transporte, controle de qualidade e farmacovigilância</b>, além de checar as <b>interações fármaco-nutriente</b>.", "tag": "Terapia nutricional"}]}, {"nome": "Índice terapêutico estreito", "icone": "🎯", "cor": "#7A2F55", "cards": [{"f": "O que é índice terapêutico estreito (ITE)?", "v": "Razão pequena entre <b>dose/concentração tóxica e a eficaz</b> (DL50/DE50 baixo) — a faixa entre \"não funciona\" e \"intoxica\" é mínima.<br>• Macete: <b>\"corda bamba\"</b> — pequena variação de dose = grande variação de efeito.<br>• Exige monitorização terapêutica (TDM).", "tag": "Conceitos"}, {"f": "Quais são as 5 indicações clássicas para solicitar TDM?", "v": "• Fármaco de <b>índice terapêutico estreito</b> com relação nível-efeito conhecida<br>• Suspeita de <b>toxicidade</b> ou de <b>falha terapêutica/má adesão</b><br>• <b>Interações</b> ou mudança de função renal/hepática<br>• Cinética <b>imprevisível</b> (não linear, alta variabilidade)<br>• Ausência de marcador clínico fácil de medir", "tag": "Conceitos"}, {"f": "Diferencie concentração de VALE (trough) e de PICO.", "v": "• <b>Vale</b> = menor concentração, colhida <b>imediatamente ANTES da próxima dose</b> → avalia <b>toxicidade/acúmulo</b> (e eficácia de tempo-dependentes).<br>• <b>Pico</b> = maior concentração após distribuição → avalia <b>eficácia</b> de concentração-dependentes.<br>Macete: <b>vale = veneno; pico = potência</b>.", "tag": "Conceitos"}, {"f": "Após quantas meias-vidas se atinge o estado de equilíbrio (steady state)?", "v": "<b>4 a 5 meias-vidas</b> (~94–97% do platô) com dose fixa e intervalo fixo.<br>• Só colher nível de rotina <b>após o steady state</b>; antes disso subestima o valor final.<br>• Mesma regra vale para o <b>washout</b> ao suspender.", "tag": "Conceitos"}, {"f": "Faixa terapêutica clássica da digoxina e alvo na insuficiência cardíaca?", "v": "• Faixa geral: <b>0,5–2,0 ng/mL</b>.<br>• Na <b>IC com FE reduzida o alvo é MENOR: 0,5–0,9 ng/mL</b> (níveis ≥1,2 associaram-se a mais mortalidade).<br>• Na FA, controle de FC pode exigir níveis um pouco maiores.", "tag": "Digoxina"}, {"f": "Qual o momento CORRETO de colher a digoxinemia?", "v": "<b>Pelo menos 6–8 h após a dose</b> (idealmente 12–24 h / imediatamente antes da próxima).<br>• Antes disso a distribuição tecidual não terminou → nível <b>falsamente alto</b>.<br>• Steady state só após ~<b>7 dias</b> (meia-vida ~36–48 h; mais na IRC).", "tag": "Digoxina"}, {"f": "Quais distúrbios eletrolíticos AUMENTAM a toxicidade da digoxina?", "v": "<b>HipoK, hipoMg e hiperCa</b> — mnemônico <b>\"K↓ Mg↓ Ca↑\"</b> ou <b>\"POTÁSSIO E MAGNÉSIO BAIXOS, CÁLCIO ALTO\"</b>.<br>• A hipocalemia libera o sítio da Na/K-ATPase para a digoxina.<br>• Somam-se: <b>disfunção renal</b>, idade avançada, hipotireoidismo, hipóxia.", "tag": "Digoxina"}, {"f": "Sinais e sintomas de intoxicação digitálica.", "v": "• <b>GI</b>: náusea, vômito, anorexia, dor abdominal (mais precoces)<br>• <b>Visuais</b>: <b>xantopsia</b> (visão amarelada), halos, borramento<br>• <b>Neuro</b>: confusão, cefaleia, fraqueza<br>• <b>Cardíacos</b>: bradicardia, BAV, extrassístoles, <b>taquicardia atrial com bloqueio</b> (quase patognomônica)", "tag": "Digoxina"}, {"f": "Amiodarona, verapamil, quinidina e claritromicina + digoxina: o que acontece e qual a conduta?", "v": "Inibem a <b>glicoproteína-P</b> (e reduzem clearance) → <b>digoxinemia sobe</b>.<br>• Conduta: <b>reduzir a dose de digoxina em ~50%</b> e monitorar o nível.<br>• Macete: <b>\"AVA-Q-C\"</b> — Amiodarona, Verapamil, Ciclosporina, Quinidina, Claritromicina (+ propafenona, itraconazol).", "tag": "Digoxina"}, {"f": "Indicações do anticorpo antidigoxina (Fab) e uma pegadinha pós-uso.", "v": "• Arritmia ventricular grave, bradiarritmia refratária à atropina, <b>K &gt; 5,0</b> na intoxicação aguda (marcador de gravidade — <b>não corrigir com cálcio IV</b>), ingestão &gt;10 mg ou nível <b>&gt;10 ng/mL</b>.<br>• <b>Pegadinha</b>: após o Fab a <b>digoxinemia total fica altíssima e inútil</b> (mede a droga ligada ao anticorpo) — guiar pela clínica.", "tag": "Digoxina"}, {"f": "Faixa terapêutica do lítio e quando colher.", "v": "• Manutenção: <b>0,6–1,0 (até 1,2) mEq/L</b>; mania aguda 0,8–1,2.<br>• Colher <b>12 h após a última dose</b> (vale de 12 h), após 5 dias no mesmo esquema.<br>• <b>>1,5</b> = tóxico; <b>>2,5</b> = grave/risco de vida.", "tag": "Lítio"}, {"f": "Quais fármacos aumentam a litemia e por quê?", "v": "<b>Tiazídicos, AINEs, IECA/BRA</b> (mnemônico <b>\"TAI\"</b>) — reduzem a excreção renal de lítio (o lítio é reabsorvido junto com o sódio no túbulo proximal).<br>• Também: metronidazol, inibidores da COX-2.<br>• <b>Cafeína e teofilina reduzem</b> a litemia.", "tag": "Lítio"}, {"f": "Por que desidratação e dieta hipossódica são perigosas com lítio?", "v": "O lítio compete com o <b>sódio</b> na reabsorção tubular: com <b>hiponatremia/hipovolemia</b> o rim reabsorve mais lítio → <b>intoxicação</b>.<br>• Orientar hidratação e <b>ingesta constante de sal</b>; cuidado com vômitos, diarreia, febre, calor e diuréticos.", "tag": "Lítio"}, {"f": "Manifestações de intoxicação por lítio e indicação de hemodiálise.", "v": "• Leve: tremor <b>grosseiro</b>, náusea, diarreia. Grave: ataxia, disartria, <b>rebaixamento, convulsão, arritmia</b>.<br>• <b>Hemodiálise</b>: nível <b>>4,0 mEq/L</b>, ou <b>>2,5</b> com sintomas graves/IRA, ou incapacidade de excretar.<br>• Crônico: <b>DI nefrogênico</b> e <b>hipotireoidismo</b>.", "tag": "Lítio"}, {"f": "Qual o alvo ATUAL de monitorização da vancomicina no MRSA?", "v": "<b>AUC24/CIM entre 400 e 600</b> (assumindo CIM ≤1 mg/L), por equação bayesiana ou 2 níveis.<br>• O antigo alvo de <b>vale 15–20 µg/mL foi abandonado</b> como meta primária (mais nefrotoxicidade sem mais eficácia) — consenso ASHP/IDSA/SIDP 2020.", "tag": "Vancomicina"}, {"f": "Se só houver o vale de vancomicina disponível, qual valor usar e quando colher?", "v": "• Vale de <b>10–15 µg/mL</b> (infecções graves/MRSA, 15–20 em esquemas antigos), sempre <b>>10</b> para evitar resistência.<br>• Colher <b>imediatamente antes da 4ª ou 5ª dose</b> (steady state).<br>• Colher antes do steady state é <b>erro clássico de prova</b>.", "tag": "Vancomicina"}, {"f": "Fatores de risco para nefrotoxicidade por vancomicina.", "v": "• <b>AUC24 > 600</b> (ou vale >20), duração <b>>7 dias</b>, dose >4 g/dia<br>• Associação com <b>piperacilina-tazobactam</b>, aminoglicosídeos, anfotericina B, contraste, AINE<br>• Instabilidade hemodinâmica, UTI, idoso, nefropatia prévia", "tag": "Vancomicina"}, {"f": "Síndrome do homem vermelho: mecanismo e conduta (pegadinha clássica).", "v": "<b>NÃO é alergia/IgE</b> — é liberação <b>direta de histamina</b> por <b>infusão rápida</b>.<br>• Prevenção: infundir em <b>≥60 min</b> (máx. <b>1 g/h</b> ou 10 mg/min).<br>• Conduta: parar/lentificar + <b>anti-histamínico</b>; <b>não contraindica</b> reuso da vancomicina.", "tag": "Vancomicina"}, {"f": "Por que aminoglicosídeo em DOSE ÚNICA DIÁRIA é preferido às múltiplas doses?", "v": "São <b>concentração-dependentes</b> (eficácia por <b>Cmáx/CIM ≥ 8–10</b>) e têm <b>efeito pós-antibiótico</b> prolongado.<br>• Pico alto = mais morte bacteriana; <b>vale baixo/indetectável</b> = menos acúmulo tubular → <b>menos nefrotoxicidade</b>.<br>• Evitar em gestante, grande queimado, endocardite, IRC grave, neonato.", "tag": "Aminoglicosídeos"}, {"f": "Pico e vale-alvo da GENTAMICINA/tobramicina em esquema de múltiplas doses.", "v": "• <b>Pico 5–10 µg/mL</b> (8–10 em infecção grave; 3–5 em sinergismo)<br>• <b>Vale &lt;2 µg/mL</b> (&lt;1 em dose única diária)<br>• Pico: colher <b>30 min após o TÉRMINO</b> da infusão de 30 min; vale: 30 min antes da dose.", "tag": "Aminoglicosídeos"}, {"f": "Pico e vale-alvo da AMICACINA.", "v": "• Múltiplas doses: <b>pico 20–30 µg/mL</b> e <b>vale &lt;5–10 µg/mL</b><br>• Dose única diária (15–20 mg/kg): pico 50–60, <b>vale &lt;5</b><br>• Macete: a amicacina é a \"irmã grande\" da gentamicina — <b>números ~4×</b> maiores.", "tag": "Aminoglicosídeos"}, {"f": "Compare nefro e ototoxicidade dos aminoglicosídeos.", "v": "• <b>Nefro</b>: NTA <b>não oligúrica e REVERSÍVEL</b>, tardia (5–7 dias); correlaciona com <b>vale elevado</b>.<br>• <b>Oto/vestibulotoxicidade</b>: zumbido, perda de agudos, vertigem — geralmente <b>IRREVERSÍVEL</b>; correlaciona com <b>exposição cumulativa/duração</b>.<br>• Macete: <b>\"o rim perdoa, o ouvido não\"</b>.", "tag": "Aminoglicosídeos"}, {"f": "Faixa terapêutica da fenitoína (total e livre) e correlação clínica dos níveis.", "v": "• Total <b>10–20 µg/mL</b>; <b>livre 1–2 µg/mL</b> (~10%).<br>• &gt;20 <b>nistagmo</b>; &gt;30 <b>ataxia/disartria</b>; &gt;40 <b>letargia/coma</b>.<br>• Macete: <b>\"20 balança os olhos, 30 balança o corpo, 40 apaga\"</b>.", "tag": "Anticonvulsivantes"}, {"f": "Por que a cinética da fenitoína é chamada de não linear/saturável?", "v": "Segue <b>Michaelis-Menten</b>: as enzimas saturam dentro da faixa terapêutica → passa de <b>1ª ordem para ordem ZERO</b>.<br>• Pequeno aumento de dose (ex.: 300→400 mg) causa <b>aumento desproporcional</b> do nível.<br>• Ajustar em <b>incrementos pequenos</b> (25–50 mg) e <b>nunca</b> usar regra de três.", "tag": "Anticonvulsivantes"}, {"f": "Como corrigir a fenitoinemia na hipoalbuminemia? (fórmula de Sheiner-Tozer)", "v": "<b>C corrigida = C medida ÷ [(0,2 × albumina) + 0,1]</b><br>• Se <b>ClCr &lt; 10 mL/min</b> ou diálise: usar <b>0,1</b> no lugar de 0,2.<br>• Alternativa melhor: dosar a <b>fenitoína LIVRE</b> (alvo 1–2 µg/mL).", "tag": "Anticonvulsivantes"}, {"f": "Principais interações da fenitoína.", "v": "• É <b>indutor potente do CYP3A4</b> → reduz contraceptivos, varfarina (a longo prazo), ciclosporina, corticoides, quinidina.<br>• <b>Ácido valproico</b>: desloca da albumina + inibe metabolismo → <b>fração livre sobe com nível total normal</b>.<br>• Sofre inibição por: fluconazol, isoniazida, amiodarona, cloranfenicol, omeprazol.", "tag": "Anticonvulsivantes"}, {"f": "Carbamazepina: faixa terapêutica e o fenômeno da AUTOINDUÇÃO.", "v": "• Faixa <b>4–12 µg/mL</b>.<br>• <b>Autoindução do CYP3A4</b>: em 2–4 semanas induz o próprio metabolismo — meia-vida cai de ~35 h para ~5–27 h → <b>o nível DESPENCA com a mesma dose</b>.<br>• Conduta: reavaliar nível <b>após ~1 mês</b> e escalonar a dose.", "tag": "Anticonvulsivantes"}, {"f": "Ácido valproico: faixa, particularidade da ligação proteica e toxicidades.", "v": "• Faixa <b>50–100 µg/mL</b> (até 125 em mania).<br>• Ligação à albumina é <b>SATURÁVEL</b>: em níveis altos/hipoalbuminemia a <b>fração livre dispara</b> — nível total subestima a toxicidade.<br>• <b>Hepatotoxicidade</b>, pancreatite, trombocitopenia, teratogenicidade (defeito de tubo neural).", "tag": "Anticonvulsivantes"}, {"f": "Paciente em valproato com sonolência/confusão, TGO-TGP e nível terapêuticos. O que investigar?", "v": "<b>Encefalopatia hiperamonêmica</b> — dosar <b>amônia sérica</b>; ocorre mesmo com nível e transaminases normais.<br>• Conduta: <b>suspender o valproato</b>; considerar <b>L-carnitina</b> nos casos graves.", "tag": "Anticonvulsivantes"}, {"f": "Fenobarbital: faixa terapêutica e implicação da meia-vida longa.", "v": "• Faixa <b>15–40 µg/mL</b> (sedação acima de 40).<br>• Meia-vida <b>70–120 h</b> → steady state só em <b>2–3 semanas</b>: dosar antes disso é inútil; ajustes demoram a se refletir.<br>• <b>Indutor enzimático potente</b> (CYP2C, 3A4 e glicuronidação).", "tag": "Anticonvulsivantes"}, {"f": "Teofilina: faixa terapêutica e sinais de toxicidade.", "v": "• Faixa <b>10–20 µg/mL</b> (alguns adotam 5–15 na asma para reduzir eventos).<br>• Toxicidade: náusea/vômito, <b>taquiarritmia</b>, tremor, insônia, <b>convulsão</b> (pode ser a 1ª manifestação), <b>hipocalemia e hiperglicemia</b>.", "tag": "Teofilina"}, {"f": "Como tabagismo e ciprofloxacino alteram a teofilinemia?", "v": "• <b>Fumo (e maconha) INDUZ CYP1A2</b> → clearance sobe ~50% (precisa de dose maior). <b>Parar de fumar</b> → nível dispara em ~1 semana: <b>reduzir a dose</b>.<br>• <b>Ciprofloxacino</b>, fluvoxamina, eritromicina, cimetidina <b>inibem CYP1A2</b> → intoxicação.<br>• Reduzem clearance também: <b>IC, cirrose, febre viral, idade avançada</b>.", "tag": "Teofilina"}, {"f": "Como se monitora ciclosporina e tacrolimo, e quais as faixas usuais?", "v": "• Pelo <b>C0 (vale, imediatamente antes da dose)</b>; alguns centros usam <b>C2</b> para ciclosporina.<br>• <b>Ciclosporina C0 ~100–400 ng/mL</b> (maior no pós-transplante imediato, menor na manutenção).<br>• <b>Tacrolimo C0 5–15 ng/mL</b> (manutenção 5–10). Variação conforme órgão, tempo e método.", "tag": "Imunossupressores"}, {"f": "Interações de ciclosporina/tacrolimo (CYP3A4 e P-gp) — quem sobe e quem desce?", "v": "• <b>Aumentam o nível</b> (inibidores): azóis (cetoconazol, voriconazol), macrolídeos, <b>diltiazem/verapamil</b>, ritonavir e <b>suco de toranja</b> (inibe o CYP3A4 intestinal).<br>• <b>Reduzem</b> (indutores): <b>rifampicina</b>, fenitoína, carbamazepina, fenobarbital, <b>erva-de-são-joão</b> → risco de <b>rejeição</b>.", "tag": "Imunossupressores"}, {"f": "Creatinina subindo em transplantado: como diferenciar nefrotoxicidade do inibidor de calcineurina x rejeição?", "v": "• <b>Nível ALTO + Cr alta</b> → provável <b>nefrotoxicidade</b> (vasoconstrição da aferente): reduzir a dose.<br>• <b>Nível BAIXO + Cr alta</b> → provável <b>rejeição</b>: otimizar dose/imunossupressão.<br>• A <b>biópsia</b> é quem define nos casos duvidosos.", "tag": "Imunossupressores"}, {"f": "Metotrexato em altas doses: quais níveis-alvo e como é o resgate?", "v": "• Nomograma: <b>24 h &lt;10 µmol/L; 48 h &lt;1; 72 h &lt;0,1</b>.<br>• <b>Ácido folínico (leucovorina)</b> iniciado ~24 h após o MTX, mantido até nível &lt;0,05–0,1, + <b>hiper-hidratação e alcalinização urinária (pH &gt;7)</b>.<br>• Eliminação atrasada/IRA grave: <b>glucarpidase</b>. Evitar AINE, sulfa, penicilinas, IBP e omeprazol.", "tag": "Metotrexato"}, {"f": "Varfarina: alvos de INR e como conduzir INR alto.", "v": "• Alvo <b>2,0–3,0</b> (FA, TVP/TEP); <b>2,5–3,5</b> em prótese <b>mecânica mitral</b>.<br>• INR &lt;4,5 sem sangramento: <b>omitir dose</b>. 4,5–10: omitir, vitamina K não é rotina. <b>&gt;10</b>: <b>vitamina K oral 2,5–5 mg</b>.<br>• <b>Sangramento grave</b>: <b>CCP (4 fatores) + vitamina K 10 mg IV lenta</b>.", "tag": "Varfarina"}, {"f": "Por que o INR demora a responder e quais interações mais aumentam o risco de sangramento?", "v": "Depende da queda dos fatores <b>II, VII, IX e X</b> — o efeito pleno leva <b>~5–7 dias</b> (fator II tem meia-vida ~60 h).<br>• Aumentam INR: <b>metronidazol, sulfametoxazol-trimetoprima, fluconazol, amiodarona, ciprofloxacino</b>, AINE (risco de sangramento).<br>• Reduzem: <b>rifampicina, carbamazepina, vitamina K da dieta</b> (verduras verde-escuras — manter ingesta CONSTANTE, não zerar).", "tag": "Varfarina"}, {"f": "Princípio do ajuste proporcional de dose no TDM — e onde ele NÃO vale.", "v": "Em <b>cinética de 1ª ordem</b>: <b>Dose nova = dose atual × (nível-alvo ÷ nível medido)</b>.<br>• <b>NÃO se aplica à fenitoína</b> (cinética saturável) — nela, incrementos pequenos (25–50 mg).<br>• Mudar a <b>dose</b> altera o nível médio; mudar o <b>intervalo</b> altera a diferença pico-vale.", "tag": "Ajuste de dose"}, {"f": "Nível fora da faixa terapêutica: quais 4 perguntas fazer ANTES de mudar a dose?", "v": "1) A coleta foi no <b>momento certo</b> e em <b>steady state</b>?<br>2) Houve erro de amostra (colheu no <b>mesmo acesso</b> da infusão, tubo com gel/heparina)?<br>3) Há <b>má adesão</b>, interação nova ou mudança de função renal/hepática/albumina?<br>4) O que diz a <b>CLÍNICA</b>? Macete: <b>trate o paciente, não o número</b>.", "tag": "Ajuste de dose"}]}, {"nome": "Infecção hospitalar, PGA & ATB", "icone": "🦠", "cor": "#0A6E64", "cards": [{"f": "O que define uma IRAS e quais são suas 4 principais topografias?", "v": "Infecção adquirida <b>após a admissão</b>, sem estar presente nem em incubação na entrada (marco prático: <b>≥48h</b>) — inclui infecção pós-alta relacionada à internação/procedimento.<br>• Topografias: <b>PAV</b> (pneumonia associada à ventilação) • <b>ITU</b> associada a cateter vesical • <b>IPCS</b> associada a cateter central • <b>ISC</b> (sítio cirúrgico).", "tag": "IRAS"}, {"f": "Como se define PAV e o que muda entre precoce e tardia?", "v": "Pneumonia que surge <b>≥48h após intubação/início da VM</b> (ou até 48h da extubação).<br>• <b>Precoce</b> (&lt;4-5 dias): flora comunitária — <i>S. pneumoniae</i>, <i>H. influenzae</i>, MSSA.<br>• <b>Tardia</b> (≥5 dias): risco de MDR — <i>P. aeruginosa</i>, <i>Acinetobacter</i>, MRSA, enterobactérias ESBL/KPC.", "tag": "IRAS"}, {"f": "Cite as medidas do bundle de prevenção da PAV.", "v": "• <b>Cabeceira elevada 30-45°</b><br>• <b>Interrupção diária da sedação</b> + teste de respiração espontânea (extubar cedo)<br>• <b>Higiene oral</b> com antisséptico e aspiração de secreção subglótica<br>• Pressão do <i>cuff</i> adequada, circuitos sem condensado e profilaxias (TEV/úlcera de estresse) conforme protocolo.", "tag": "IRAS"}, {"f": "Qual a medida isolada mais eficaz para reduzir ITU associada a cateter vesical?", "v": "<b>Retirar o cateter o mais precocemente possível</b> — e só indicá-lo quando realmente necessário (retenção, monitorização crítica de diurese, cirurgia).<br>• Complementos: inserção asséptica, <b>sistema de drenagem fechado</b>, bolsa <b>abaixo do nível da bexiga</b> sem tocar o chão, sem trocas/irrigações de rotina.<br>• <b>Não</b> se previne ITU com antimicrobiano profilático.", "tag": "IRAS"}, {"f": "Quais itens compõem o bundle de inserção de cateter venoso central?", "v": "• <b>Higiene das mãos</b><br>• <b>Barreira máxima de precaução</b> (gorro, máscara, avental e luvas estéreis, campo amplo)<br>• Antissepsia da pele com <b>clorexidina alcoólica &gt;0,5%</b><br>• Escolha do sítio (evitar femoral) + <b>avaliação diária da necessidade</b> do cateter e cuidado de curativo/conectores (<i>scrub the hub</i>).", "tag": "IRAS"}, {"f": "Como se classifica a ISC e até quando ela é considerada relacionada à cirurgia?", "v": "• <b>Incisional superficial</b> (pele/subcutâneo) • <b>Incisional profunda</b> (fáscia/músculo) • <b>Órgão/cavidade</b>.<br>• Vigilância até <b>30 dias</b> na maioria dos procedimentos e até <b>90 dias</b> quando há <b>implante/prótese</b> (profunda e órgão-cavidade).", "tag": "IRAS"}, {"f": "CCIH x SCIH: qual a diferença e qual a base legal?", "v": "<b>CCIH</b> = comissão <b>deliberativa/consultiva</b>, multiprofissional, obrigatória em todo hospital (Lei 9.431/1997 e Portaria MS 2.616/1998); <b>SCIH</b> = serviço <b>executor</b>, membros consultores.<br>• Produtos: PCIRAS, vigilância epidemiológica, protocolos, treinamento e <b>perfil de sensibilidade local (antibiograma cumulativo)</b>.", "tag": "IRAS"}, {"f": "Cite 4 atribuições do farmacêutico clínico na CCIH/PGA.", "v": "• Construir e monitorar a <b>padronização e o protocolo de antimicrobianos</b> (restrição, ajuste renal/hepático)<br>• <b>Auditoria prospectiva com feedback</b>, descalonamento e transição IV→VO<br>• Calcular <b>indicadores de consumo (DDD/DOT)</b> e correlacioná-los com a resistência<br>• Farmacovigilância, monitorização terapêutica (vanco/aminoglicosídeo) e educação da equipe.", "tag": "IRAS"}, {"f": "O que são precauções padrão e para quem se aplicam?", "v": "Aplicam-se a <b>TODOS os pacientes</b>, independentemente do diagnóstico ou suspeita.<br>• <b>Higiene das mãos</b>, EPI conforme risco de exposição (luvas, avental, máscara/óculos), <b>descarte seguro de perfurocortantes</b>, etiqueta respiratória e processamento adequado de artigos/superfícies.<br>• Premissa: <b>todo sangue e fluido corporal é potencialmente infectante</b>.", "tag": "Precauções"}, {"f": "Precaução de CONTATO: quais EPI e 3 exemplos clássicos?", "v": "<b>Avental + luvas</b> na entrada do quarto, quarto privativo (ou coorte) e artigos de uso exclusivo.<br>• Exemplos: <b>bactérias multirresistentes</b> (MRSA, VRE, KPC), <b>Clostridioides difficile</b>, <b>escabiose/pediculose</b>, diarreia por norovírus/rotavírus, herpes zoster localizado em imunossuprimido.", "tag": "Precauções"}, {"f": "Precaução por GOTÍCULAS: qual máscara, qual distância e quais doenças?", "v": "<b>Máscara cirúrgica</b> ao entrar no quarto; partículas &gt;5 µm que caem em até <b>~1 a 2 metros</b>; quarto privativo, <b>sem</b> pressão negativa.<br>• Exemplos: <b>meningite meningocócica</b>, <b>influenza</b>, <b>coqueluche</b>, caxumba, rubéola, difteria faríngea.<br>• Macete: <b>“MICA” — Meningo, Influenza, Coqueluche, cAxumba</b>.", "tag": "Precauções"}, {"f": "Precaução por AEROSSÓIS: requisitos e quais doenças?", "v": "<b>N95/PFF2</b> + <b>quarto com pressão negativa</b>, porta fechada, ≥6-12 trocas de ar/h; máscara cirúrgica no paciente ao sair.<br>• Doenças: <b>tuberculose pulmonar/laríngea, sarampo, varicela e herpes zoster disseminado</b> — os dois últimos exigem <b>aerossol + contato</b>.<br>• Macete: <b>“TuBa-SaVa”</b> (TB, Sarampo, Varicela).", "tag": "Precauções"}, {"f": "Quais são os 5 momentos da higiene das mãos da OMS?", "v": "1) <b>Antes de tocar o paciente</b><br>2) <b>Antes de procedimento asséptico/limpo</b><br>3) <b>Após risco de exposição a fluidos corporais</b><br>4) <b>Após tocar o paciente</b><br>5) <b>Após contato com superfícies próximas ao paciente</b>.<br>• Macete: <b>2 “antes”</b> (paciente/procedimento) e <b>3 “após”</b> (fluido, paciente, ambiente).", "tag": "Precauções"}, {"f": "Quando o álcool 70% NÃO substitui água e sabão?", "v": "• <b>Mãos visivelmente sujas</b> ou com sangue/fluidos<br>• <b>Clostridioides difficile</b> e <b>norovírus</b> — o álcool não elimina <b>esporos</b> nem vírus não envelopados (a remoção é <b>mecânica</b>)<br>• Após uso do banheiro.<br>• No ambiente do <i>C. difficile</i> a desinfecção de superfícies exige <b>hipoclorito</b>.", "tag": "Precauções"}, {"f": "Classificação de Spaulding: os 3 tipos de artigo e o processamento de cada um.", "v": "• <b>Crítico</b> — entra em tecido estéril/sistema vascular (bisturi, cateter, agulha) → <b>esterilização</b><br>• <b>Semicrítico</b> — contato com mucosa/pele não íntegra (endoscópio, laringoscópio, circuito respiratório) → <b>desinfecção de alto nível</b><br>• <b>Não crítico</b> — pele íntegra (estetoscópio, esfigmo, comadre) → limpeza/<b>desinfecção de baixo ou médio nível</b>.", "tag": "Precauções"}, {"f": "Desinfecção de alto nível x esterilização: o que cada uma elimina?", "v": "• <b>Alto nível</b>: destrói microrganismos vegetativos, micobactérias, fungos e vírus, mas <b>não garante morte de esporos</b> — glutaraldeído, ácido peracético, OPA.<br>• <b>Esterilização</b>: elimina <b>toda forma de vida, inclusive esporos</b> — <b>autoclave (vapor saturado sob pressão, padrão-ouro)</b>, óxido de etileno, peróxido de hidrogênio plasma.<br>• Regra: <b>não existe esterilização sem limpeza prévia</b>.", "tag": "Precauções"}, {"f": "Quais são os objetivos de um PGA (stewardship)?", "v": "• <b>Otimizar o desfecho clínico</b> (droga, dose, via, duração corretas)<br>• <b>Reduzir eventos adversos</b>, incluindo toxicidade e <b>infecção por C. difficile</b><br>• <b>Conter a pressão seletiva e a resistência</b><br>• Reduzir custo é <b>consequência</b>, nunca o objetivo principal.", "tag": "PGA"}, {"f": "Quais são as duas estratégias CENTRAIS do stewardship e o trade-off de cada uma?", "v": "• <b>Auditoria prospectiva com feedback</b> (pós-prescrição): não trava o início da terapia, é educativa e bem aceita — porém depende de equipe e a adesão é voluntária.<br>• <b>Restrição/pré-autorização</b>: controle imediato de consumo e custo, age antes da 1ª dose — porém pode atrasar o tratamento, gerar atrito e deslocar o uso para outras classes.", "tag": "PGA"}, {"f": "O que é descalonamento e em que momento ele deve ser feito?", "v": "Trocar o esquema <b>empírico amplo</b> pelo <b>mais estreito e eficaz</b>, guiado por cultura/antibiograma e evolução clínica, no <b>“time-out” de 48-72h</b>.<br>• Inclui <b>suspender coberturas desnecessárias</b> (ex.: retirar vancomicina sem MRSA) e reduzir combinação a monoterapia.<br>• Descalonar <b>não piora desfecho</b> — reduz resistência, toxicidade e custo.", "tag": "PGA"}, {"f": "Terapia empírica x dirigida: o que define cada uma?", "v": "• <b>Empírica</b>: iniciada <b>sem o agente identificado</b>, guiada por foco provável, gravidade, fatores de risco para MDR e <b>perfil microbiológico local</b>; precoce na sepse.<br>• <b>Dirigida</b>: ajustada ao <b>patógeno e à CIM do antibiograma</b>, com o espectro mais estreito possível.<br>• Regra: <b>colher culturas antes</b> é o que permite sair da empírica.", "tag": "PGA"}, {"f": "Qual a tendência atual sobre tempo de terapia antimicrobiana?", "v": "<b>Cursos curtos são tão eficazes quanto os longos</b> na maioria das infecções não complicadas (“<i>shorter is better</i>”).<br>• Exemplos: PAC ~5 dias (afebril 48-72h e estável), pneumonia hospitalar/PAV ~7 dias, ITU não complicada 3-5 dias, PBE 5 dias.<br>• Exceções de curso longo: <b>endocardite, osteomielite, abscesso não drenado, bacteremia por S. aureus</b>.", "tag": "PGA"}, {"f": "Quais critérios autorizam a transição IV → VO? (mnemônico)", "v": "<b>COMS</b>: <b>C</b>línica melhorando e estável (afebril ~24-48h) • <b>O</b>ral — TGI funcionante, sem vômito/íleo/má absorção • <b>M</b>arcadores em queda (leucócitos/PCR) • <b>S</b>em indicação obrigatória de IV (endocardite, meningite, abscesso não drenado, bacteremia por <i>S. aureus</i>).<br>• Preferir drogas de <b>alta biodisponibilidade oral</b>: fluoroquinolonas, linezolida, metronidazol, fluconazol, SMZ-TMP, clindamicina, doxiciclina.", "tag": "PGA"}, {"f": "DDD x DOT: o que medem e qual é o indicador preferido?", "v": "• <b>DDD</b> = dose diária definida (OMS): gramas consumidas ÷ DDD padrão, por <b>100 leitos-dia</b> — compara instituições, mas <b>distorce em disfunção renal, obesidade e pediatria</b>.<br>• <b>DOT</b> = <b>dias de terapia</b> por 1.000 pacientes-dia, independe da dose → <b>preferido</b> (cada droga conta 1 DOT/dia).<br>• <b>DOT/LOT</b> (dias de terapia ÷ dias de tratamento) estima o grau de terapia combinada.", "tag": "PGA"}, {"f": "Betalactâmico x aminoglicosídeo: qual índice PK/PD prediz a eficácia de cada um?", "v": "• <b>Tempo-dependentes</b>: betalactâmicos — alvo <b>fT&gt;CIM</b> → otimiza-se <b>fracionando a dose ou prolongando a infusão</b>.<br>• <b>Concentração-dependentes</b>: <b>aminoglicosídeos</b>, fluoroquinolonas e daptomicina — alvos <b>Cmáx/CIM</b> e <b>AUC/CIM</b> → dose maior e mais espaçada.<br>• Vancomicina e linezolida dependem de <b>AUC/CIM</b>.", "tag": "Uso racional"}, {"f": "Qual a lógica da infusão estendida/contínua de betalactâmicos e 2 exemplos?", "v": "Aumentar o <b>fT&gt;CIM</b> sem elevar a dose total — útil em <b>paciente grave, CIM elevada e clearance renal aumentado</b>.<br>• <b>Piperacilina-tazobactam em 4h</b> e <b>meropenem em 3h</b>, após dose de ataque em bólus.<br>• Cuidados do farmacêutico: <b>estabilidade físico-química</b> da solução, compatibilidade e acesso venoso dedicado.", "tag": "Uso racional"}, {"f": "Qual o alvo atual de monitorização da vancomicina e o principal risco?", "v": "Alvo <b>AUC24/CIM entre 400 e 600</b> (consenso 2020) — substituiu o vale de 15-20 mg/L, associado a mais <b>nefrotoxicidade</b>.<br>• Dose de ataque <b>25-30 mg/kg</b> (peso real) em infecção grave.<br>• A reação de infusão (“síndrome do homem vermelho”) é <b>histaminérgica, não alérgica</b> → infundir em ≥60 min e reduzir a velocidade.", "tag": "Uso racional"}, {"f": "Por que o aminoglicosídeo em dose única diária é preferível ao esquema fracionado?", "v": "• Explora a farmacodinâmica <b>concentração-dependente</b> (maior <b>Cmáx/CIM</b>) e o <b>efeito pós-antibiótico</b> prolongado<br>• Reduz a <b>captação saturável</b> no túbulo renal e na cóclea → <b>menos nefro e ototoxicidade</b><br>• Evitar o esquema estendido em <b>gestante, endocardite, grande queimado</b> e disfunção renal significativa.", "tag": "Uso racional"}, {"f": "Profilaxia cirúrgica: em que momento a dose deve ser infundida?", "v": "Concluir a infusão <b>dentro de 60 minutos antes da incisão</b> — o objetivo é nível tecidual adequado <b>no momento do corte</b>.<br>• <b>120 minutos</b> para drogas de infusão lenta: <b>vancomicina e fluoroquinolonas</b>.<br>• <b>Cefazolina</b> é a escolha na maioria das cirurgias limpas e limpas-contaminadas (cobre MSSA e estreptococos).", "tag": "Uso racional"}, {"f": "Profilaxia cirúrgica: quando redosar e por quanto tempo manter?", "v": "• <b>Redose intraoperatória</b> a cada <b>~2 meias-vidas</b> da droga (cefazolina a cada 3-4h) ou após <b>perda sanguínea &gt;1.500 mL</b>.<br>• <b>Duração: dose única</b> na maioria dos casos; <b>não ultrapassar 24h</b> após o fim da cirurgia — nem na presença de dreno ou cateter.<br>• Prolongar <b>não reduz ISC</b> e aumenta resistência, lesão renal e <i>C. difficile</i>.", "tag": "Uso racional"}, {"f": "Hemocultura: quantos frascos, de onde e quando colher?", "v": "• <b>2 a 3 pares</b> (aeróbio + anaeróbio) de <b>punções/sítios distintos</b><br>• <b>Sempre ANTES da 1ª dose</b> do antimicrobiano — sem atrasar o início na sepse<br>• <b>O volume é o fator que mais aumenta a positividade</b> (8-10 mL por frasco no adulto)<br>• Suspeita de infecção de cateter: colher par <b>periférico + do cateter</b> (tempo diferencial de positivação).", "tag": "Uso racional"}, {"f": "Colonização x infecção: por que isso muda a conduta? Dê o exemplo clássico.", "v": "<b>Colonização</b> = microrganismo presente <b>sem resposta inflamatória/clínica</b> → em regra <b>não se trata</b>.<br>• Exemplo: <b>bacteriúria assintomática</b> — tratar apenas <b>gestantes</b> e antes de <b>procedimento urológico invasivo</b> com risco de sangramento de mucosa.<br>• Aspirado traqueal, ponta de cateter e swab de ferida positivos <b>sem clínica</b> não indicam antibiótico.", "tag": "Uso racional"}, {"f": "ESBL: o que é, em quais bactérias e qual o tratamento de escolha?", "v": "<b>Betalactamase de espectro estendido</b> (classe A de Ambler, inibida por clavulanato) — hidrolisa <b>penicilinas, cefalosporinas (inclusive 3ª/4ª geração) e aztreonam</b>; <b>não</b> hidrolisa carbapenêmicos.<br>• Típica de <i>E. coli</i> e <i>K. pneumoniae</i>.<br>• Infecção grave: <b>carbapenêmico</b>; cistite não complicada: opções poupadoras (fosfomicina, nitrofurantoína).", "tag": "Resistência"}, {"f": "AmpC: mecanismo, quais germes e por que a cefalosporina de 3ª geração é armadilha?", "v": "Cefalosporinase <b>cromossômica indutível</b> (classe C), <b>não inibida por clavulanato</b> — pode desreprimir durante o tratamento e o paciente <b>falha mesmo com antibiograma inicialmente sensível</b>.<br>• Macete <b>“ESCAPPM”</b>: <i>Enterobacter, Serratia, Citrobacter freundii, Aeromonas/Hafnia, Proteus vulgaris, Providencia, Morganella</i>.<br>• Preferir <b>cefepima</b> ou <b>carbapenêmico</b> (evitar ceftriaxona).", "tag": "Resistência"}, {"f": "KPC: que tipo de enzima é e quais as opções terapêuticas?", "v": "<b>Carbapenemase de classe A (serina)</b>, plasmidial, típica de <i>K. pneumoniae</i> — hidrolisa <b>todos os betalactâmicos, inclusive carbapenêmicos</b>.<br>• Opções: <b>ceftazidima-avibactam</b>, meropenem-vaborbactam, imipenem-relebactam.<br>• Alternativas/associações: polimixina B, tigeciclina (<b>não</b> em ITU nem bacteremia), amicacina, fosfomicina.", "tag": "Resistência"}, {"f": "Metalobetalactamase (MBL): quais enzimas e qual a “brecha” terapêutica?", "v": "<b>NDM, VIM, IMP</b> — classe B, dependentes de <b>zinco</b>, <b>não inibidas por avibactam/vaborbactam</b>.<br>• <b>Brecha: não hidrolisam o aztreonam</b>; como a cepa costuma carregar ESBL/AmpC junto, usa-se <b>aztreonam + ceftazidima-avibactam</b> ou <b>cefiderocol</b>.<br>• Macete: <b>MBL = Metal (zinco) → aztreonaM escapa</b>.", "tag": "Resistência"}, {"f": "MRSA: qual o mecanismo genético e a implicação prática imediata?", "v": "Gene <b>mecA</b> → <b>PBP2a</b>, com baixa afinidade pelos betalactâmicos → resistência a <b>TODOS os betalactâmicos</b> (exceto ceftarolina).<br>• Infecção grave: <b>vancomicina</b>, daptomicina ou linezolida — <b>daptomicina não serve para pneumonia</b> (inativada pelo surfactante).<br>• Comunitário leve: SMZ-TMP, clindamicina, doxiciclina. Controle: <b>precaução de contato</b>.", "tag": "Resistência"}, {"f": "VRE: qual o gene mais relevante e como tratar?", "v": "<b>vanA</b> — resistência de alto nível a <b>vancomicina E teicoplanina</b> (troca do alvo D-Ala-D-Ala por D-Ala-D-Lac); <b>vanB</b> costuma poupar a teicoplanina.<br>• Tratamento: <b>linezolida</b> ou <b>daptomicina</b> (bacteremia/endocardite).<br>• <i>E. faecium</i> é mais resistente que <i>E. faecalis</i>; controle por <b>precaução de contato</b>.", "tag": "Resistência"}, {"f": "Defina MDR, XDR e PDR.", "v": "• <b>MDR</b>: não sensível a <b>≥1 agente em ≥3 categorias</b> de antimicrobianos<br>• <b>XDR</b>: não sensível a ≥1 agente em <b>todas as categorias, exceto 1 ou 2</b><br>• <b>PDR</b>: não sensível a <b>todos os agentes de todas as categorias</b><br>• Macete: <b>M</b>ulti (3 classes) → <b>X</b>tensivo (sobram 1-2) → <b>P</b>an (não sobra nada).", "tag": "Resistência"}, {"f": "RDC 20/2011 (ANVISA): o que ela exige na dispensação de antimicrobianos?", "v": "Controla venda e uso de antimicrobianos: receita <b>em 2 vias</b>, com <b>retenção da 2ª via</b> pela farmácia e carimbo/data na 1ª, devolvida ao paciente.<br>• <b>Validade de 10 dias</b> da emissão; quantidade limitada ao tratamento prescrito.<br>• <b>Escrituração obrigatória no SNGPC</b> e guarda dos registros; trata-se de <b>receita simples</b> (não é receituário de controle especial).", "tag": "Uso racional"}, {"f": "Relacione o antimicrobiano ao efeito adverso mais cobrado.", "v": "• <b>Vancomicina</b>: nefrotoxicidade e reação de infusão • <b>Aminoglicosídeo</b>: nefro + ototoxicidade e bloqueio neuromuscular<br>• <b>Linezolida</b>: <b>mielossupressão &gt;14 dias</b>, neuropatia e <b>síndrome serotoninérgica</b> (IMAO fraco)<br>• <b>Daptomicina</b>: <b>elevação de CPK/miopatia</b> • <b>Fluoroquinolona</b>: tendinopatia, <b>QT longo</b>, disglicemia • <b>Polimixina</b>: nefro e neurotoxicidade.<br>• Mais associados a <i>C. difficile</i>: <b>clindamicina, cefalosporinas e quinolonas</b>.", "tag": "Uso racional"}]}, {"nome": "Interações medicamentosas", "icone": "🔀", "cor": "#8A6A12", "cards": [{"f": "Qual a diferença entre interação FARMACOCINÉTICA e FARMACODINÂMICA?", "v": "• <b>Farmacocinética</b>: um fármaco altera <b>ADME</b> do outro → muda a <b>concentração</b> (nível sérico) do fármaco-objeto.<br>• <b>Farmacodinâmica</b>: agem no <b>mesmo receptor/sistema</b> → muda o <b>efeito</b> sem mudar o nível.<br>Macete: <b>cinética = quanto chega; dinâmica = o que faz</b>. Quem sofre é o <b>objeto</b>; quem causa é o <b>precipitante</b>.", "tag": "Interações medicamentosas"}, {"f": "Defina sinergismo ADITIVO, POTENCIAÇÃO e ANTAGONISMO.", "v": "• <b>Aditivo</b>: 1+1=2 (dois AINEs; dois depressores do SNC).<br>• <b>Potenciação/supra-aditivo</b>: 1+1>2, ou um fármaco <b>sem efeito próprio amplia</b> o do outro (SMZ+TMP; clavulanato+amoxicilina).<br>• <b>Antagonismo</b>: 1+1<1 — reduz o efeito (naloxona×morfina; vitamina K×varfarina; AINE×anti-hipertensivo).", "tag": "Interações medicamentosas"}, {"f": "Interação na ABSORÇÃO por QUELAÇÃO: mecanismo e sentido do efeito.", "v": "Cátions <b>di/trivalentes</b> (Ca²⁺, Mg²⁺, Al³⁺, Fe²⁺, Zn²⁺) formam <b>complexo insolúvel não absorvível</b> → <b>REDUZ</b> a biodisponibilidade do antibiótico/hormônio.<br>Conduta: <b>espaçar</b> (2 h antes ou 4–6 h depois), nunca suspender às cegas.", "tag": "Interações medicamentosas"}, {"f": "Como alteração do pH gástrico e da MOTILIDADE modificam a absorção?", "v": "• <b>pH</b>: IBP/antiácido <b>elevam</b> o pH e <b>REDUZEM</b> a absorção de fármacos que precisam de meio ácido (cetoconazol, itraconazol cápsula, atazanavir, sais de ferro).<br>• <b>Motilidade</b>: metoclopramida <b>acelera</b> (↑velocidade, geralmente sem mudar a extensão); opioides/anticolinérgicos <b>retardam</b> o esvaziamento → pico mais tardio.", "tag": "Interações medicamentosas"}, {"f": "Interação na DISTRIBUIÇÃO: o que é deslocamento proteico e quando importa?", "v": "Fármaco com <b>maior afinidade</b> pela albumina desloca o outro → <b>AUMENTA</b> a fração <b>livre</b> (ativa) transitoriamente.<br>Risco real só em fármacos <b>muito ligados (>90%), baixo Vd e índice terapêutico estreito</b>: <b>varfarina, fenitoína, metotrexato</b>, deslocados por AAS, sulfonamidas, valproato.<br>Cuidado: na <b>fenitoína</b> o nível TOTAL pode vir normal com livre alta.", "tag": "Interações medicamentosas"}, {"f": "Interação na EXCREÇÃO por competição tubular: cite exemplos e o sentido.", "v": "Competem pelo mesmo <b>transportador tubular (OAT/OCT)</b> → <b>REDUZ a secreção</b> e <b>AUMENTA</b> o nível do outro.<br>• <b>Probenecida + penicilina</b> (↑nível — uso terapêutico).<br>• <b>AINE/SMZ-TMP + metotrexato</b> (↑MTX — tóxico).<br>• <b>Tiazídico/IECA + lítio</b> (↑lítio).<br>Também conta o <b>pH urinário</b>: alcalinização ioniza ácidos fracos e ↑ excreção (AAS, fenobarbital).", "tag": "Interações medicamentosas"}, {"f": "Regra de ouro: qual o SENTIDO do efeito de um INDUTOR enzimático sobre o substrato?", "v": "Indutor <b>aumenta a síntese da enzima</b> → <b>acelera o metabolismo</b> → <b>REDUZ</b> o nível e o efeito do substrato → <b>falha terapêutica</b>.<br>Exceção perigosa: se o substrato for <b>pró-fármaco</b>, o indutor <b>AUMENTA</b> o metabólito ativo/tóxico (ex.: paracetamol + etanol crônico → ↑NAPQI).<br>Instalação <b>lenta: 1–2 semanas</b> (precisa transcrever proteína) e o efeito <b>persiste dias após retirar</b>.", "tag": "Interações medicamentosas"}, {"f": "Regra de ouro: qual o SENTIDO do efeito de um INIBIDOR enzimático sobre o substrato?", "v": "Inibidor <b>bloqueia a enzima</b> → <b>reduz o metabolismo</b> → <b>AUMENTA</b> o nível do substrato → <b>toxicidade</b>.<br>Instalação <b>rápida: 24–48 h</b> (basta ocupar a enzima).<br>Se o substrato for <b>pró-fármaco</b>, inverte: o inibidor <b>REDUZ</b> o efeito (clopidogrel, codeína, tramadol).", "tag": "Interações medicamentosas"}, {"f": "Mnemônico dos principais INDUTORES do CYP450.", "v": "<b>“CRAFTES”</b>: <b>C</b>arbamazepina, <b>R</b>ifampicina, <b>A</b>lcool crônico, <b>F</b>enitoína/<b>F</b>enobarbital, <b>T</b>abaco (CYP1A2), <b>E</b>rva-de-são-joão (hipérico), <b>S</b>ulfoniluréias/griseofulvina.<br>Todos <b>REDUZEM</b> o nível do substrato. A <b>rifampicina</b> é o indutor mais potente (3A4 + P-gp).", "tag": "Interações medicamentosas"}, {"f": "Mnemônico dos principais INIBIDORES do CYP450.", "v": "<b>“CAMPO FRIO”</b> ou os <b>-azóis, -micinas e -navir</b>: <b>C</b>etoconazol/itraconazol/fluconazol, <b>A</b>miodarona, <b>M</b>acrolídeos (claritro/eritro; azitromicina NÃO), <b>P</b>aroxetina/fluoxetina, <b>O</b>meprazol (2C19), <b>F</b>luvoxamina, <b>R</b>itonavir, <b>I</b>soniazida/<b>c</b>imetidina, <b>O</b>utros: ciprofloxacino e <b>suco de toranja</b>.<br>Todos <b>AUMENTAM</b> o nível do substrato.", "tag": "Interações medicamentosas"}, {"f": "Por que o TABAGISMO reduz o efeito de clozapina, olanzapina e teofilina?", "v": "Os <b>hidrocarbonetos policíclicos da fumaça</b> (não a nicotina) <b>induzem o CYP1A2</b> → <b>REDUZEM</b> o nível desses fármacos (fumantes precisam de doses maiores).<br>Pegadinha: ao <b>parar de fumar</b> (ou internar), a indução cessa em ~1 semana e o nível <b>SOBE</b> → risco de intoxicação. Reduzir dose e monitorar.", "tag": "Interações medicamentosas"}, {"f": "Etanol AGUDO x CRÔNICO: qual induz e qual inibe? Consequência com paracetamol.", "v": "• <b>Agudo (porre)</b>: <b>INIBE</b> o CYP2E1 (compete) → <b>AUMENTA</b> o nível de outros fármacos (ex.: benzodiazepínico → sedação).<br>• <b>Crônico</b>: <b>INDUZ</b> CYP2E1 → <b>AUMENTA a formação de NAPQI</b> a partir do paracetamol → <b>hepatotoxicidade com doses menores</b> (limitar a 2 g/dia).", "tag": "Interações medicamentosas"}, {"f": "ERVA-DE-SÃO-JOÃO (Hypericum perforatum): mecanismo e 4 vítimas clássicas.", "v": "<b>Indutor</b> potente de <b>CYP3A4 + P-gp</b> → <b>REDUZ</b> o nível de: <b>anticoncepcional</b> (sangramento/gravidez), <b>ciclosporina/tacrolimo</b> (rejeição), <b>varfarina</b> (↓INR), <b>antirretrovirais</b> e digoxina.<br>Além disso é <b>serotoninérgico</b>: com ISRS → <b>síndrome serotoninérgica</b>. Contraindicada em transplantado e HIV.", "tag": "Interações medicamentosas"}, {"f": "SUCO DE TORANJA (grapefruit): mecanismo, sentido e duração.", "v": "<b>Furanocumarinas</b> inibem <b>irreversivelmente o CYP3A4 INTESTINAL</b> (e a P-gp) → ↑ biodisponibilidade → <b>AUMENTA</b> o nível de sinvastatina/atorvastatina (rabdomiólise), amlodipino/felodipino (hipotensão), ciclosporina, amiodarona.<br>Efeito dura <b>até 24–72 h</b> — espaçar o horário NÃO resolve; orientar <b>suspender</b> a fruta/suco.<br>Não afeta pravastatina, rosuvastatina nem fluvastatina.", "tag": "Interações medicamentosas"}, {"f": "Por que OMEPRAZOL reduz o efeito do CLOPIDOGREL?", "v": "Clopidogrel é <b>PRÓ-FÁRMACO</b> ativado pelo <b>CYP2C19</b>. O omeprazol/esomeprazol <b>inibe o 2C19</b> → <b>MENOS metabólito ativo</b> → <b>REDUZ a antiagregação</b> → risco de trombose de stent.<br>Conduta: trocar por <b>pantoprazol</b> (menor inibição) ou usar prasugrel/ticagrelor.<br>Macete: <b>inibidor + pró-fármaco = menos efeito</b>.", "tag": "Interações medicamentosas"}, {"f": "Por que fluoxetina/paroxetina reduzem a analgesia da CODEÍNA e do TRAMADOL?", "v": "Ambos são <b>pró-fármacos do CYP2D6</b> (codeína → <b>morfina</b>; tramadol → <b>O-desmetiltramadol</b>). Fluoxetina, paroxetina, bupropiona e quinidina <b>inibem o 2D6</b> → <b>REDUZ</b> o metabólito ativo → <b>falha analgésica</b>.<br>Agravante: ISRS + tramadol também <b>AUMENTA o risco de síndrome serotoninérgica e convulsão</b>.", "tag": "Interações medicamentosas"}, {"f": "POLIMORFISMO do CYP2D6: o que acontece com codeína no metabolizador LENTO e no ULTRARRÁPIDO?", "v": "• <b>Lento (PM)</b>: pouco converte → <b>sem analgesia</b> (parece “resistente ao opioide”).<br>• <b>Ultrarrápido (UM)</b>: converte demais → <b>excesso de morfina</b> → depressão respiratória; <b>contraindicada em crianças e lactantes</b> (óbitos de RN amamentados).<br>Outros polimorfismos de prova: <b>CYP2C9/VKORC1</b> (varfarina), <b>CYP2C19</b> (clopidogrel), <b>TPMT</b> (azatioprina), <b>NAT2</b> (isoniazida).", "tag": "Interações medicamentosas"}, {"f": "Paciente em uso de RIFAMPICINA/carbamazepina inicia anticoncepcional oral. Qual o risco e a conduta?", "v": "Indutores <b>REDUZEM</b> o nível de estrogênio/progestagênio → <b>falha contraceptiva e sangramento de escape</b>.<br>Conduta: <b>método adicional de barreira</b> durante o uso e por <b>28 dias após</b>, ou trocar por método não dependente de CYP (<b>DIU de cobre, DIU hormonal, injetável trimestral</b>).<br>Vale também para fenitoína, fenobarbital, erva-de-são-joão e alguns antirretrovirais.", "tag": "Interações medicamentosas"}, {"f": "FENITOÍNA + ÁCIDO VALPROICO: por que o nível total pode enganar?", "v": "Interação <b>dupla</b>: o valproato <b>desloca</b> a fenitoína da albumina <b>e inibe</b> seu metabolismo → a <b>fenitoína LIVRE AUMENTA</b> (toxicidade: nistagmo, ataxia, sonolência) enquanto a <b>total pode estar normal ou baixa</b>.<br>Conduta: dosar <b>fenitoína livre</b> e avaliar clínica, não corrigir dose só pelo nível total.<br>Lembrar: fenitoína tem <b>cinética de ordem zero</b> — pequeno aumento de dose = grande salto no nível.", "tag": "Interações medicamentosas"}, {"f": "Transportador P-gp: o que acontece com a DIGOXINA quando se associa verapamil, amiodarona ou claritromicina?", "v": "Esses fármacos <b>INIBEM a P-gp</b> (bomba de efluxo intestinal e renal) → menos digoxina é bombeada para fora → <b>AUMENTA</b> a digoxinemia → <b>intoxicação digitálica</b> (náusea, xantopsia, bradiarritmia).<br>Conduta: <b>reduzir a dose de digoxina em ~30–50%</b> e monitorar nível sérico e potássio.<br>Ao contrário, <b>rifampicina induz a P-gp</b> → <b>REDUZ</b> a digoxina.", "tag": "Interações medicamentosas"}, {"f": "OATP1B1 (SLCO1B1) e estatinas: qual o mecanismo e a consequência?", "v": "O OATP1B1 faz a <b>captação hepática</b> das estatinas. Se for <b>inibido</b> (ciclosporina, genfibrozila, rifampicina em dose única) ou houver <b>polimorfismo SLCO1B1</b>, a estatina <b>fica no plasma/músculo</b> → <b>AUMENTA</b> a exposição sistêmica → <b>miopatia e rabdomiólise</b>.<br>Mais relatado com <b>sinvastatina</b>; limitar dose e monitorar CPK e queixa muscular.", "tag": "Interações medicamentosas"}, {"f": "Por que a CICLOSPORINA é um “coringa” de interações?", "v": "É <b>substrato</b> de CYP3A4/P-gp <b>e inibidora</b> de CYP3A4, <b>P-gp e OATP1B1</b>. Logo:<br>• Inibidores 3A4 (azóis, macrolídeos, toranja) <b>AUMENTAM</b> a ciclosporina → nefrotoxicidade.<br>• Indutores (rifampicina, hipérico) <b>REDUZEM</b> → <b>rejeição do enxerto</b>.<br>• Ela <b>AUMENTA</b> estatinas (rabdomiólise), digoxina e colchicina.<br>Sempre <b>monitorar nível sérico</b> a cada mudança de esquema.", "tag": "Interações medicamentosas"}, {"f": "VARFARINA: cite fármacos que AUMENTAM e que REDUZEM o INR.", "v": "<b>↑ INR / sangramento</b> (inibem CYP2C9 ou deslocam): <b>metronidazol, SMZ-TMP, fluconazol, amiodarona, ciprofloxacino, claritromicina, fluoxetina, AAS/AINE, omeprazol</b>.<br>• <b>↓ INR / trombose</b> (indutores): <b>rifampicina, carbamazepina, fenitoína, fenobarbital, erva-de-são-joão</b> e excesso de <b>vitamina K</b>.<br>Macete: <b>“antibiótico quase sempre sobe o INR”</b> (também mata a flora produtora de vitamina K). Conduta: <b>monitorar INR em 3–5 dias</b>.", "tag": "Interações medicamentosas"}, {"f": "Por que AINE e SMZ-TMP são perigosos com METOTREXATO?", "v": "• <b>AINE</b>: competem pela <b>secreção tubular</b> e reduzem o fluxo renal → <b>AUMENTAM</b> o MTX → mielossupressão, mucosite, nefrotoxicidade.<br>• <b>SMZ-TMP</b>: soma <b>antifolato + deslocamento proteico + competição tubular</b> → <b>pancitopenia</b> (associação a evitar).<br>Também interagem: <b>IBP</b> (↑MTX em dose alta) e probenecida. Conduta: <b>evitar/substituir</b> e monitorar hemograma e função renal.", "tag": "Interações medicamentosas"}, {"f": "IMAO + alimentos ricos em TIRAMINA: qual a interação e o quadro clínico?", "v": "A <b>MAO intestinal</b> normalmente degrada a tiramina; inibida, a tiramina é absorvida e <b>libera noradrenalina</b> → <b>crise hipertensiva</b> (“reação do queijo”): cefaleia occipital pulsátil, rigidez de nuca, hipertensão grave, AVC.<br>Evitar: <b>queijos envelhecidos, embutidos, vinho tinto, chope, molho de soja, extrato de levedura, alimentos fermentados</b>.<br>Vale para tranilcipromina, fenelzina e <b>linezolida</b> (IMAO fraco).", "tag": "Interações medicamentosas"}, {"f": "IMAO + ISRS: qual o risco e qual o intervalo de segurança (washout)?", "v": "Associação <b>proibida</b>: excesso serotoninérgico → <b>síndrome serotoninérgica</b> potencialmente fatal.<br>Washout: <b>≥14 dias</b> entre IMAO e ISRS; para a <b>FLUOXETINA</b>, esperar <b>5 semanas</b> (meia-vida longa da norfluoxetina).<br>Mesma lógica vale para <b>linezolida, azul de metileno, selegilina</b>.", "tag": "Interações medicamentosas"}, {"f": "SÍNDROME SEROTONINÉRGICA: tríade clínica, agentes envolvidos e conduta.", "v": "Tríade: <b>alteração mental + hiperatividade autonômica + hiperatividade neuromuscular (clônus/hiperreflexia, mais em MMII)</b>, com <b>hipertermia</b>.<br>Combinações de prova: <b>ISRS/IRSN + tramadol, linezolida, IMAO, triptanos, fentanil, ondansetrona, lítio, erva-de-são-joão</b>.<br>Conduta: <b>suspender o serotoninérgico</b>, suporte, benzodiazepínico; caso grave, <b>ciproeptadina</b>.<br>Diferencial: instalação em <b>horas</b> e <b>clônus</b> (a síndrome neuroléptica maligna é em dias, com rigidez em “cano de chumbo”).", "tag": "Interações medicamentosas"}, {"f": "ALOPURINOL + AZATIOPRINA/mercaptopurina: mecanismo e conduta.", "v": "O alopurinol <b>inibe a xantina oxidase</b>, principal via de inativação da <b>6-mercaptopurina</b> (metabólito da azatioprina) → <b>AUMENTA</b> muito o nível → <b>mielossupressão grave/pancitopenia</b>.<br>Conduta: <b>evitar</b>; se indispensável, <b>reduzir a azatioprina a 25–33% da dose</b> com hemograma seriado. Considerar dosar <b>TPMT</b>.<br>Vale também o febuxostate.", "tag": "Interações medicamentosas"}, {"f": "LÍTIO: quais três classes elevam a litemia e por quê?", "v": "Todas <b>reduzem a excreção renal</b> de lítio → <b>AUMENTAM</b> a litemia → tremor grosseiro, ataxia, confusão, convulsão.<br>• <b>Tiazídicos</b> (depleção de sódio → ↑reabsorção proximal de Li⁺).<br>• <b>AINEs</b> (↓prostaglandinas → ↓fluxo renal).<br>• <b>IECA/BRA</b>.<br>Macete: <b>“LITIO = Lítio + IECA + Tiazídico + Ibuprofeno = Overdose”</b>. Conduta: preferir <b>AAS/paracetamol</b>, manter hidratação e dosar litemia.", "tag": "Interações medicamentosas"}, {"f": "ESTATINA + fibrato ou macrolídeo: qual o risco e como conduzir?", "v": "<b>Risco de miopatia/rabdomiólise</b> (dor muscular + ↑CPK + mioglobinúria → IRA).<br>• <b>Genfibrozila</b> inibe glicuronidação e OATP1B1 → <b>AUMENTA</b> a estatina (pior par; preferir <b>fenofibrato</b>).<br>• <b>Claritromicina/eritromicina, azóis, verapamil, amiodarona</b> inibem CYP3A4 → <b>AUMENTAM</b> sinvastatina/atorvastatina.<br>Conduta: <b>suspender a estatina durante o macrolídeo</b> ou trocar por <b>pravastatina/rosuvastatina</b> (não dependem de 3A4).", "tag": "Interações medicamentosas"}, {"f": "IECA/BRA + ESPIRONOLACTONA (ou suplemento de K⁺): interação e monitorização.", "v": "Interação <b>farmacodinâmica ADITIVA</b>: IECA ↓aldosterona e espironolactona bloqueia seu receptor → ambos <b>retêm potássio</b> → <b>HIPERCALEMIA</b> (arritmia, onda T apiculada).<br>Somam risco: <b>AINE, heparina, SMZ-TMP, betabloqueador, DRC e diabetes</b>.<br>Conduta: dosar <b>K⁺ e creatinina em 7–14 dias</b> após início/aumento de dose e orientar dieta.", "tag": "Interações medicamentosas"}, {"f": "Por que furosemida e tiazídicos aumentam a toxicidade da DIGOXINA?", "v": "Causam <b>HIPOCALEMIA e hipomagnesemia</b>; o K⁺ compete com a digoxina pelo mesmo sítio da <b>Na⁺/K⁺-ATPase</b> → com K⁺ baixo a digoxina liga mais → <b>AUMENTA o efeito/toxicidade sem mudar o nível sérico</b> (interação farmacodinâmica).<br>Sinais: náusea, <b>xantopsia (visão amarelada)</b>, bradicardia, arritmias.<br>Conduta: <b>corrigir e monitorar K⁺ e Mg²⁺</b>.", "tag": "Interações medicamentosas"}, {"f": "TEOFILINA + CIPROFLOXACINO: mecanismo e desfecho.", "v": "O ciprofloxacino (e a fluvoxamina, e a cessação do tabagismo) <b>INIBE o CYP1A2</b> → <b>AUMENTA</b> a teofilina, que tem <b>índice terapêutico estreito</b> → <b>náusea, taquiarritmia e convulsão</b>.<br>Conduta: <b>evitar</b> ou reduzir a dose e dosar o nível sérico (faixa 10–20 mcg/mL).<br>Ao contrário, <b>tabaco/rifampicina induzem 1A2 e REDUZEM</b> a teofilina.", "tag": "Interações medicamentosas"}, {"f": "METRONIDAZOL + ÁLCOOL: que efeito ocorre e por quanto tempo orientar abstinência?", "v": "<b>Efeito dissulfiram-símile</b>: inibe a <b>aldeído-desidrogenase</b> → <b>acúmulo de acetaldeído</b> → rubor, cefaleia latejante, náusea/vômito, taquicardia, hipotensão.<br>Orientar <b>abstinência durante o tratamento e por 48–72 h após</b> (72 h para tinidazol).<br>Mesmo efeito: <b>cefalosporinas com cadeia NMTT (cefamandol, cefoperazona), griseofulvina, clorpropamida, dissulfiram</b>.", "tag": "Interações medicamentosas"}, {"f": "Quinolona, tetraciclina, levotiroxina e bifosfonato: qual a orientação de horário frente a antiácido, cálcio ou ferro?", "v": "Todos são <b>quelados</b> por cátions → <b>REDUZ</b> a absorção (queda de até 50–90%).<br>• <b>Quinolona/tetraciclina</b>: tomar <b>2 h antes ou 4–6 h depois</b> do antiácido, leite, cálcio, ferro, zinco, sucralfato.<br>• <b>Levotiroxina</b>: <b>jejum</b>, 30–60 min antes do café; afastar <b>4 h</b> de cálcio, ferro, IBP, colestiramina.<br>• <b>Bifosfonato</b>: jejum, <b>só com água</b>, de pé por 30 min.", "tag": "Interações medicamentosas"}, {"f": "VARFARINA e vitamina K da dieta: qual a orientação correta ao paciente?", "v": "Antagonismo <b>farmacodinâmico</b>: vegetais verde-escuros (couve, espinafre, brócolis, alface, fígado, chá verde) <b>REDUZEM o INR</b> → risco de trombose.<br>Orientação: <b>NÃO proibir</b> — manter uma <b>ingestão CONSTANTE</b> de vitamina K; o problema é a <b>variação</b>.<br>Atenção também a <b>álcool agudo (↑INR)</b> e a suplementos de <b>ômega-3, ginkgo, alho e ginseng</b> (↑sangramento).", "tag": "Interações medicamentosas"}, {"f": "Como o ALIMENTO altera a biodisponibilidade? Dê exemplos nos dois sentidos.", "v": "• <b>Alimento AUMENTA</b> (lipofílicos, retardo gástrico + bile): <b>itraconazol cápsula, griseofulvina, saquinavir, carbamazepina, cefuroxima axetil</b> → tomar <b>com</b> comida.<br>• <b>Alimento REDUZ</b>: <b>levotiroxina, bifosfonato, ampicilina, captopril, rifampicina, isoniazida</b> → tomar em <b>jejum</b>.<br>• <b>Reduz irritação</b> sem mudar absorção: AINE, metformina, corticoide → <b>com</b> alimento.", "tag": "Interações medicamentosas"}, {"f": "Cite 4 FITOTERÁPICOS/suplementos de risco e a interação de cada um.", "v": "• <b>Erva-de-são-joão</b>: indutor 3A4/P-gp → <b>REDUZ</b> anticoncepcional, ciclosporina, varfarina, antirretroviral; + ISRS → serotoninérgica.<br>• <b>Ginkgo biloba, alho, gengibre, ômega-3</b>: antiagregação → <b>AUMENTAM</b> o sangramento com varfarina/AAS.<br>• <b>Ginseng</b>: ↓INR e hipoglicemia com antidiabético.<br>• <b>Efedra/cáscara, camomila</b>: cardiotoxicidade e ↑sedação/anticoagulação (cumarinas).", "tag": "Interações medicamentosas"}, {"f": "Que critérios definem a RELEVÂNCIA CLÍNICA de uma interação (e não só a teórica)?", "v": "Avaliar: <b>índice terapêutico do objeto</b> (varfarina, digoxina, lítio, fenitoína, teofilina, imunossupressor, MTX = alerta máximo); <b>gravidade e evidência</b> (Micromedex/Lexi: contraindicada, grave, moderada); <b>via e dose</b>; <b>tempo de exposição</b> (dose única × uso crônico); <b>fatores do paciente</b>: idoso, <b>polifarmácia (≥5 fármacos)</b>, DRC/hepatopatia, genética.<br>Regra: <b>interação teórica ≠ interação clinicamente significativa</b>.", "tag": "Interações medicamentosas"}, {"f": "Quais são as 5 condutas do farmacêutico diante de uma interação detectada?", "v": "Mnemônico <b>“MEASN”</b>:<br>• <b>M</b>onitorar (INR, K⁺, nível sérico, CPK, clínica);<br>• <b>E</b>spaçar horários (quelação, pH);<br>• <b>A</b>justar dose (↓digoxina com amiodarona; ↓azatioprina com alopurinol);<br>• <b>S</b>ubstituir por alternativa segura (pantoprazol, azitromicina, pravastatina, fenofibrato);<br>• <b>N</b>otificar/registrar: comunicar o prescritor, documentar em prontuário, orientar o paciente e <b>notificar em farmacovigilância</b> se houver evento adverso.", "tag": "Interações medicamentosas"}]}, {"nome": "Processo de cuidado", "icone": "🤝", "cor": "#1F5C86", "cards": [{"f": "Diferencie <b>atenção farmacêutica</b> de <b>cuidado farmacêutico</b>.", "v": "• <b>Atenção farmacêutica</b> (Consenso Brasileiro, 2002): modelo de prática com interação direta farmacêutico-paciente e corresponsabilidade pelos resultados da farmacoterapia.<br>• <b>Cuidado farmacêutico</b> (<i>pharmaceutical care</i>, Hepler & Strand, 1990): termo atual, mais amplo, que engloba todos os serviços clínicos e a gestão do cuidado.", "tag": "Conceitos"}, {"f": "O que é <b>seguimento farmacoterapêutico</b> e o que o distingue dos demais serviços clínicos?", "v": "Serviço <b>longitudinal e continuado</b> em que o farmacêutico avalia toda a farmacoterapia, detecta e resolve <b>PRM/RNM</b> e monitora resultados ao longo do tempo.<br>• Diferencial: <b>continuidade + registro + metas pactuadas</b> (≠ ato pontual como a dispensação).<br>• <b>Revisão</b> da farmacoterapia é pontual; <b>seguimento</b> é no tempo.", "tag": "Conceitos"}, {"f": "Dispensação x orientação farmacêutica: qual a diferença técnica?", "v": "• <b>Dispensação</b>: ato de <b>avaliar a prescrição</b> e fornecer o medicamento <b>acompanhado de orientação</b> (CFF 585) — é serviço clínico, não entrega de balcão.<br>• <b>Orientação</b>: componente educativo/informacional, que ocorre dentro da dispensação ou isoladamente.", "tag": "Conceitos"}, {"f": "O que estabelece a <b>Resolução CFF 585/2013</b>?", "v": "Regulamenta as <b>atribuições clínicas</b> do farmacêutico: anamnese e exame físico voltados à farmacoterapia, <b>acesso e registro em prontuário</b>, consulta farmacêutica em consultório, solicitação de exames complementares e encaminhamento a outros profissionais.", "tag": "Conceitos"}, {"f": "O que a <b>Resolução CFF 586/2013</b> autoriza e quais os limites?", "v": "Regula a <b>prescrição farmacêutica</b>:<br>• <b>Sem diagnóstico prévio</b>: apenas MIPs, produtos de livre acesso e terapias não farmacológicas, para <b>problemas autolimitados</b>.<br>• <b>Com diagnóstico prévio</b>: medicamentos sob prescrição, somente dentro de <b>protocolo/programa</b> acordado com a equipe.", "tag": "Conceitos"}, {"f": "O que é o <b>modelo ECHO</b> de resultados em farmácia clínica?", "v": "Macete <b>ECHO</b> (Kozma, 1993) — os 3 tipos de resultado:<br>• <b>E</b>conomic: custos diretos/indiretos, custo evitado<br>• <b>C</b>linical: PA, HbA1c, RAM, reinternação, mortalidade<br>• <b>H</b>umanistic <b>O</b>utcomes: qualidade de vida, satisfação, funcionalidade.", "tag": "Conceitos"}, {"f": "Cite <b>indicadores de processo</b> e <b>de resultado</b> do serviço de cuidado farmacêutico.", "v": "• <b>Processo</b>: nº de conciliações na admissão, intervenções por paciente-dia, <b>taxa de aceitação</b> das intervenções, cobertura de consultas.<br>• <b>Resultado</b>: metas terapêuticas atingidas, RNM resolvidos, reinternação em 30 dias, eventos adversos evitados, custo evitado.", "tag": "Conceitos"}, {"f": "Quais são as <b>4 etapas</b> do processo de cuidado ao paciente? (macete)", "v": "Macete <b>C-A-P-A</b>:<br>• <b>C</b>oleta de dados (subjetivos + objetivos)<br>• <b>A</b>valiação/identificação dos problemas da farmacoterapia<br>• <b>P</b>lano de cuidado (metas + intervenções)<br>• <b>A</b>companhamento/monitorização — o ciclo então recomeça.", "tag": "Etapas"}, {"f": "Qual a <b>ordem lógica</b> de avaliação de cada medicamento (Cipolle/Strand)?", "v": "Macete <b>I-E-S-A</b>: <b>I</b>ndicação (é necessário?) → <b>E</b>fetividade (funciona?) → <b>S</b>egurança (é seguro?) → <b>A</b>desão/conveniência (o paciente consegue usar?).<br>• A ordem é fixa: não se avalia dose de um medicamento sem indicação.", "tag": "Etapas"}, {"f": "O que é a <b>anamnese farmacêutica</b> e como difere da médica?", "v": "Entrevista dirigida ao <b>uso de medicamentos</b>: histórico farmacoterapêutico, <b>alergias e RAM prévias</b>, automedicação, fitoterápicos e suplementos, técnica de uso do dispositivo, armazenamento e adesão.<br>• Foco no <b>processo de uso</b>, não no diagnóstico.", "tag": "Etapas"}, {"f": "O que compõe um <b>plano de cuidado</b> bem construído?", "v": "• <b>Metas terapêuticas</b> mensuráveis e <b>pactuadas</b> (parâmetro + valor + prazo)<br>• <b>Intervenções</b> farmacológicas e não farmacológicas<br>• <b>Responsável</b> por cada ação e <b>data de retorno/monitorização</b>.", "tag": "Etapas"}, {"f": "Na etapa de <b>acompanhamento/monitorização</b>, o que reavaliar?", "v": "• <b>Efetividade</b>: parâmetros clínicos e laboratoriais frente às metas<br>• <b>Segurança</b>: RAM, toxicidade, exames de monitorização<br>• <b>Adesão</b> e novos problemas de saúde/medicamentos → gera novo estado de situação (processo <b>cíclico</b>).", "tag": "Etapas"}, {"f": "Cite as etapas do <b>Método Dáder</b> (Universidade de Granada).", "v": "Oferta do serviço → <b>1ª entrevista</b> → <b>estado de situação</b> → <b>fase de estudo</b> → <b>fase de avaliação</b> → <b>fase de intervenção</b> → resultado da intervenção → entrevistas sucessivas.<br>• <b>Estado de situação</b> = \"fotografia\" que relaciona, numa data, problemas de saúde × medicamentos em uso.", "tag": "Etapas"}, {"f": "O que entra em cada letra do registro <b>SOAP</b>?", "v": "• <b>S</b>ubjetivo: relato do paciente (queixas, sintomas, adesão referida)<br>• <b>O</b>bjetivo: dados mensuráveis (PA, glicemia, exames, prescrição)<br>• <b>A</b>valiação: interpretação e PRM/RNM identificados<br>• <b>P</b>lano: intervenções, metas, monitorização e retorno.<br>Macete: <b>S = o que ele diz; O = o que se mede</b>.", "tag": "Etapas"}, {"f": "O que caracteriza uma boa <b>evolução farmacêutica</b> em prontuário?", "v": "• Registro em <b>prontuário único</b>, datado e assinado com <b>nome e CRF</b><br>• Objetiva, sem juízo de valor: <b>problema → conduta → plano de monitorização</b><br>• Documento <b>legal e sigiloso</b>: correção por ressalva datada, nunca por rasura ou apagamento.", "tag": "Etapas"}, {"f": "Cite os <b>tipos de intervenção farmacêutica</b> mais cobrados.", "v": "• Sobre o <b>medicamento</b>: inclusão, suspensão, substituição, ajuste de dose/frequência/via<br>• Sobre a <b>administração</b>: horário, diluição, incompatibilidade, tempo de infusão<br>• Sobre o <b>monitoramento</b>: solicitar exame ou nível sérico<br>• <b>Educativa</b>: orientação ao paciente ou à equipe.", "tag": "Etapas"}, {"f": "Qual o papel do farmacêutico na <b>visita/ronda multiprofissional</b>?", "v": "• Chegar com a farmacoterapia <b>já revisada</b> (indicação, ajuste renal/hepático, interações, IV→VO, desprescrição, profilaxias)<br>• Intervir em <b>tempo real</b>, com recomendação objetiva e fonte<br>• Evidência clássica: reduz erros de prescrição e eventos adversos evitáveis, sobretudo em UTI.", "tag": "Etapas"}, {"f": "Segundo o <b>Terceiro Consenso de Granada (2007)</b>, o que é <b>PRM</b>?", "v": "<b>Problema Relacionado a Medicamento</b> = elemento de <b>PROCESSO</b> (situação/causa) que pode levar a um resultado negativo.<br>• Ex.: interação, dose inadequada, erro de administração, conservação incorreta, não adesão.<br>Macete: <b>PRM = causa</b>.", "tag": "PRM/RNM"}, {"f": "O que é <b>RNM</b> e como se diferencia do PRM?", "v": "<b>Resultado Negativo associado ao Medicamento</b> = resultado <b>na saúde do paciente</b> não adequado ao objetivo da farmacoterapia.<br>Macete: <b>PRM = causa (processo)</b> × <b>RNM = consequência (resultado)</b>.", "tag": "PRM/RNM"}, {"f": "Cite os <b>6 RNM</b> do Terceiro Consenso de Granada e suas dimensões.", "v": "Macete das dimensões <b>N-E-S</b>:<br>• <b>N</b>ecessidade: problema de saúde não tratado / efeito de medicamento desnecessário<br>• <b>E</b>fetividade: inefetividade <b>não quantitativa</b> / <b>quantitativa</b><br>• <b>S</b>egurança: insegurança <b>não quantitativa</b> / <b>quantitativa</b>.", "tag": "PRM/RNM"}, {"f": "RNM <b>quantitativo</b> x <b>não quantitativo</b>: o que muda?", "v": "• <b>Quantitativo</b>: depende da <b>DOSE</b> — subdose (inefetividade quantitativa) ou superdose (insegurança quantitativa).<br>• <b>Não quantitativo</b>: independe da dose — fármaco errado ou resistência (inefetividade) e reação alérgica/idiossincrática (insegurança).", "tag": "PRM/RNM"}, {"f": "RNM x <b>reação adversa</b> x <b>erro de medicação</b>: como se relacionam?", "v": "• <b>RNM</b> é o guarda-chuva do resultado negativo.<br>• <b>RAM</b>: RNM de <b>insegurança</b> em doses usuais, não decorrente de erro.<br>• <b>Erro de medicação</b>: falha de processo (PRM), <b>evitável</b>; se causar dano, é <b>evento adverso evitável</b>.", "tag": "PRM/RNM"}, {"f": "Quais as <b>7 categorias de DRP</b> e as <b>3 fases</b> do <b>Pharmacotherapy Workup (PWDT)</b>?", "v": "• <b>DRP</b>: necessita terapia adicional • medicamento desnecessário • medicamento inefetivo • dose muito baixa • reação adversa • dose muito alta • <b>não adesão</b>.<br>• <b>Fases</b>: <i>assessment</i> → plano de cuidado → <i>follow-up evaluation</i> (Cipolle, Strand & Morley).", "tag": "PRM/RNM"}, {"f": "O que é <b>conciliação medicamentosa</b>?", "v": "Processo <b>formal</b> de obter a lista completa e acurada dos medicamentos em uso e <b>compará-la</b> com as prescrições nas transições de cuidado, resolvendo as discrepâncias <b>com o prescritor</b>.<br>• Evita omissões, duplicidades e erros de dose, via e frequência.", "tag": "Conciliação"}, {"f": "Em quais <b>3 momentos</b> a conciliação medicamentosa é obrigatória?", "v": "Macete <b>A-T-A</b>:<br>• <b>A</b>dmissão (internação)<br>• <b>T</b>ransferência (troca de setor/nível de cuidado)<br>• <b>A</b>lta hospitalar.<br>Base: programa <b>High 5s</b> da OMS e as Metas Internacionais de Segurança do Paciente.", "tag": "Conciliação"}, {"f": "O que é a <b>BPMH</b> (melhor história de medicamentos possível)?", "v": "História construída com <b>no mínimo 2 fontes</b>: entrevista estruturada com paciente/cuidador <b>+</b> receitas, caixas trazidas, prontuário, farmácia ou lista da UBS.<br>• Meta usual: realizada em até <b>24 h</b> da admissão.", "tag": "Conciliação"}, {"f": "Discrepância <b>intencional</b> x <b>não intencional</b>: defina e exemplifique.", "v": "• <b>Intencional</b>: mudança deliberada do prescritor — <b>documentada</b> (justificada) ou <b>não documentada</b> (correta, mas sem registro → risco futuro).<br>• <b>Não intencional</b> = <b>erro</b>: omissão de crônico (a mais comum), comissão, diferença de dose/via/frequência, duplicidade.", "tag": "Conciliação"}, {"f": "O que a <b>conciliação de alta</b> deve entregar ao paciente?", "v": "• Lista final reconciliada: o que <b>continua</b>, o que <b>mudou</b>, o que foi <b>suspenso</b> e o que era só hospitalar<br>• Dose, via, horários e duração em linguagem simples<br>• Sinais de alerta, data de retorno e envio da lista ao serviço de origem/APS.", "tag": "Conciliação"}, {"f": "Por que a <b>transição do cuidado</b> é ponto crítico de segurança?", "v": "• Boa parte dos erros de medicação e dos eventos adversos pós-alta nasce nas transições.<br>• Causas: fragmentação da informação, medicamentos suspensos temporariamente que não são reintroduzidos e ajustes hospitalares perpetuados sem revisão.", "tag": "Conciliação"}, {"f": "Defina <b>adesão</b> e diferencie de <b>persistência</b>.", "v": "• <b>Adesão</b> (OMS): grau em que o comportamento do paciente <b>corresponde às recomendações acordadas</b> com o profissional — pressupõe <b>concordância</b> (≠ obediência/<i>compliance</i>).<br>• <b>Persistência</b>: <b>tempo</b> de continuidade do tratamento até a descontinuação.", "tag": "Adesão"}, {"f": "Quais as <b>5 dimensões da adesão</b> segundo a OMS (2003)?", "v": "Macete <b>S-S-D-T-P</b>:<br>• fatores <b>S</b>ocioeconômicos • do <b>S</b>istema/equipe de saúde • da <b>D</b>oença (condição) • da <b>T</b>erapia • do <b>P</b>aciente.<br>Conceito-chave: adesão é <b>multifatorial</b> — não é \"culpa do paciente\".", "tag": "Adesão"}, {"f": "Não adesão <b>intencional</b> x <b>não intencional</b>: exemplos e conduta.", "v": "• <b>Não intencional</b> (não consegue): esquecimento, regime complexo, custo, limitação motora/visual → lembretes, simplificação, organizador de doses.<br>• <b>Intencional</b> (decide não usar): crenças, medo de RAM, ausência de sintomas → <b>entrevista motivacional</b> e educação.", "tag": "Adesão"}, {"f": "Cite métodos <b>diretos</b> e <b>indiretos</b> de medir adesão.", "v": "• <b>Diretos</b>: dosagem sérica/urinária do fármaco ou metabólito, marcador biológico, terapia diretamente observada — acurados, porém caros.<br>• <b>Indiretos</b>: questionários (Morisky), <b>contagem de comprimidos</b>, registros de dispensação (MPR/PDC), MEMS, autorrelato, diário.", "tag": "Adesão"}, {"f": "Como se interpreta o <b>Morisky (MMAS-4 e MMAS-8)</b>?", "v": "• <b>MMAS-4</b>: esquece? descuida do horário? para quando melhora? para quando piora? → <b>0 ponto = alta adesão</b>.<br>• <b>MMAS-8</b>: <b>&lt;6 baixa</b>, <b>6 a &lt;8 média</b>, <b>8 alta</b>.<br>• Limite: alta especificidade e baixa sensibilidade — <b>superestima</b> a adesão.", "tag": "Adesão"}, {"f": "Como se calculam a <b>contagem de comprimidos</b> e a <b>taxa de posse (MPR/PDC)</b>?", "v": "• <b>Contagem</b>: (nº dispensado − nº restante) ÷ nº prescrito no período × 100.<br>• <b>MPR/PDC</b>: dias de medicamento dispensado ÷ dias do período × 100.<br>• Corte de adesão adequada: <b>≥ 80%</b> (o PDC é o mais conservador).", "tag": "Adesão"}, {"f": "O que é <b>entrevista motivacional</b> e quais seus princípios?", "v": "Abordagem colaborativa e centrada no paciente para resolver a <b>ambivalência</b>.<br>Macete <b>RULE</b>: <b>R</b>esistir ao reflexo de corrigir • <b>U</b>nderstand (entender motivações) • <b>L</b>isten (escuta empática) • <b>E</b>mpower (fortalecer autonomia).<br>Ferramentas <b>OARS</b>: perguntas abertas, afirmação, reflexão, resumo.", "tag": "Comunicação"}, {"f": "O que é <b>letramento em saúde</b> e como adaptar a orientação a baixo letramento?", "v": "Capacidade de <b>obter, compreender e usar</b> informação em saúde para decidir.<br>• Linguagem simples, <b>3 a 5 mensagens-chave</b>, sem jargão<br>• Pictogramas, tabela de horários vinculada à rotina e <b>demonstração prática</b> do dispositivo.", "tag": "Comunicação"}, {"f": "O que é a técnica <b>teach-back</b> (ensinar de volta)?", "v": "Pedir que o paciente <b>explique com as próprias palavras</b> o que entendeu — testa a <b>qualidade da explicação do profissional</b>, não a memória do paciente.<br>• Modelo: \"Para eu ter certeza de que expliquei bem, me conte como vai usar esse remédio em casa.\"<br>• Se errar: reexplicar de outra forma e repetir o ciclo.", "tag": "Comunicação"}, {"f": "Quais informações são <b>obrigatórias na orientação da dispensação</b>?", "v": "• <b>Para que serve</b> e o que esperar do tratamento<br>• <b>Como usar</b>: dose, via, horários, relação com alimentos, técnica do dispositivo<br>• <b>Duração</b> e o que fazer se esquecer uma dose<br>• <b>RAM comuns e sinais de alerta</b>, interações relevantes e <b>conservação</b>.", "tag": "Comunicação"}, {"f": "Como <b>comunicar e registrar</b> uma intervenção farmacêutica ao prescritor?", "v": "• Preferir contato <b>verbal direto</b> (maior taxa de aceitação) + registro escrito no prontuário<br>• Estrutura <b>SBAR</b>: <b>S</b>ituação, <b>B</b>ackground, <b>A</b>valiação, <b>R</b>ecomendação<br>• Registrar: problema, evidência/fonte, sugestão objetiva e <b>desfecho (aceita ou não aceita)</b>.", "tag": "Comunicação"}]}, {"nome": "Exames laboratoriais", "icone": "🧪", "cor": "#2F6B45", "cards": [{"f": "Anemia: o VCM te joga em três caixas. Diga a caixa e a causa-chave de cada uma.", "v": "• <b>Micro (&lt;80 fL)</b>: ferropriva (mais comum), talassemia, anemia sideroblástica.<br>• <b>Normo (80-100)</b>: doença crônica/inflamatória, DRC (eritropoetina), hemorragia aguda.<br>• <b>Macro (&gt;100)</b>: B12/folato, álcool, hipotireoidismo e <b>fármacos</b> (metformina, metotrexato, hidroxiureia, zidovudina, fenitoína).<br>Macete: <b>\"pequeno = falta ferro; grande = falta vitamina\"</b>.", "tag": "Hemograma"}, {"f": "Dois pacientes com VCM 68. Um tem RDW 18%, o outro RDW 12,5%. Quem é ferropriva?", "v": "• <b>RDW alto (&gt;15%) = ferropriva</b> — a carência é progressiva, então convivem hemácias novas normais e velhas pequenas (anisocitose).<br>• <b>RDW normal = talassemia</b> — todas as hemácias são pequenas do mesmo jeito, população homogênea.<br>Macete: <b>RDW = \"Régua da Desigualdade\"</b>; ferro faz bagunça, talassemia é uniforme.", "tag": "Hemograma"}, {"f": "Reticulócitos altos x baixos: o que cada cenário diz sobre a MEDULA?", "v": "• <b>Altos (&gt;2% / IPR &gt;2)</b>: medula respondendo — perda ou destruição periférica (hemorragia, <b>hemólise</b>, inclusive imuno-hemólise por fármaco).<br>• <b>Baixos (IPR &lt;2)</b>: medula não responde — carência (ferro/B12/folato), DRC, aplasia, <b>mielotoxicidade por fármaco</b>.<br>Reticulócito é o \"termômetro da resposta medular\": pedir SEMPRE antes de rotular a anemia.", "tag": "Hemograma"}, {"f": "A partir de que contagem a neutropenia vira emergência, e o que muda na conduta farmacêutica?", "v": "• <b>Neutrófilos &lt;500/mm³</b> (ou &lt;1000 com previsão de queda) = neutropenia grave.<br>• Com <b>febre ≥38,3 °C</b> (ou 38 °C por 1h) = <b>neutropenia febril</b>: hemocultura + <b>antibiótico antipseudomonas na 1ª hora</b> (cefepima, pip-tazo, meropenem).<br>• Farmacêutico: revisar mielotóxicos (quimioterápico, clozapina, metimazol, dipirona, linezolida, ganciclovir) e checar dose/tempo do ATB empírico.", "tag": "Hemograma"}, {"f": "Plaquetas caíram para 40.000. Cite os fármacos que você revisa primeiro na prescrição.", "v": "• <b>Heparina</b> (pensar em HIT), <b>linezolida</b> (&gt;14 dias), <b>valproato</b>, vancomicina, <b>sulfametoxazol-trimetoprima</b>, quinina/quinidina, AINE, carbamazepina, glicoproteína IIb/IIIa.<br>• Antes de tudo, excluir <b>pseudoplaquetopenia por EDTA</b> (agregados no tubo roxo) → repetir em <b>citrato</b>.<br>• Regra prática: &lt;50.000 evitar antiagregante/anticoagulante eletivo; &lt;20.000 risco de sangramento espontâneo.", "tag": "Hemograma"}, {"f": "Leucocitose com desvio à esquerda x leucocitose sem infecção: como diferenciar à beira do leito?", "v": "• <b>Desvio à esquerda</b> = bastões &gt;5-10% ou surgimento de metamielócitos/mielócitos + granulações tóxicas → sugere <b>infecção bacteriana</b>.<br>• <b>Sem desvio</b>: pensar em fármaco/estresse — <b>corticoide</b> (desmarginação: neutrofilia com <b>linfopenia e eosinopenia</b>), lítio, G-CSF, adrenalina, tabagismo.<br>• <b>Eosinofilia + rash + TGP alta</b> = suspeitar de reação a fármaco (DRESS).", "tag": "Hemograma"}, {"f": "TP/INR: qual via da coagulação avalia e qual anticoagulante monitora?", "v": "• Avalia a <b>via extrínseca</b> (fator VII) e a via comum.<br>• Monitora a <b>varfarina</b> (alvo INR 2-3; 2,5-3,5 em prótese mecânica mitral).<br>• Também é marcador de <b>função de síntese hepática</b> e de deficiência de vitamina K.<br>Macete <b>\"PET\"</b>: <b>P</b>rotrombina = <b>E</b>xtrínseca = fator <b>T</b>ecidual. E \"Warfarin = We use PT\".", "tag": "Coagulação"}, {"f": "TTPa: qual via avalia, o que monitora e qual é o alvo terapêutico clássico?", "v": "• Avalia a <b>via intrínseca</b> (VIII, IX, XI, XII) e a comum.<br>• Monitora a <b>heparina não fracionada (HNF)</b> em infusão contínua; alvo <b>1,5 a 2,5× o valor basal do laboratório</b>.<br>• Prolonga também em hemofilia, anticoagulante lúpico, dabigatrana e deficiência de fatores.<br>Macete: <b>TTPa = heparina \"de bomba\"; INR = varfarina \"de comprimido\"</b>.", "tag": "Coagulação"}, {"f": "Quando o anti-Xa substitui o TTPa/é obrigatório monitorar HBPM?", "v": "• <b>HBPM</b> (enoxaparina) em <b>gestante, obeso grave, TFG &lt;30, criança, idoso muito magro</b> ou uso prolongado.<br>• <b>HNF</b> quando o TTPa não é confiável (anticoagulante lúpico, TTPa basal alargado, resistência à heparina).<br>• Coleta no <b>pico: 4 h após a dose SC</b>. Alvo enoxaparina 1 mg/kg 12/12h ≈ <b>0,6-1,0 UI/mL</b>; dose única diária ≈ 1,0-2,0.<br>• Profilaxia normalmente NÃO precisa de monitorização.", "tag": "Coagulação"}, {"f": "Por que o D-dímero \"serve para excluir e não para confirmar\" TEP/TVP?", "v": "• Tem <b>alto valor preditivo NEGATIVO</b>: negativo em paciente de probabilidade pré-teste <b>baixa/intermediária</b> praticamente exclui o evento (dispensa imagem).<br>• É <b>inespecífico</b>: sobe em idade avançada, gestação, câncer, infecção/sepse, pós-operatório, trauma, ICC.<br>• Em &gt;50 anos usar <b>ponto de corte ajustado à idade (idade × 10 ng/mL FEU)</b>.<br>Macete: <b>D-dímero é \"porta de saída\", nunca \"porta de entrada\" do diagnóstico</b>.", "tag": "Coagulação"}, {"f": "Idoso sarcopênico com creatinina 0,9 mg/dL: por que isso NÃO significa rim bom — e qual TFG usar para ajustar dose?", "v": "• Creatinina depende da <b>massa muscular</b>: idoso, sarcopênico, amputado ou desnutrido têm Cr \"normal\" com TFG baixa (a relação é <b>hiperbólica</b> — perde-se ~50% da função sem alterar a Cr).<br>• Estimar sempre por <b>CKD-EPI 2021</b> (versão SEM coeficiente de raça); usar <b>cistatina C</b> se a massa muscular for atípica.<br>• <b>Classificar DRC</b>: TFG indexada (mL/min/1,73 m²). <b>Ajustar dose</b>: TFG <b>desindexada</b> (mL/min = TFG × SC/1,73), crítico em obeso e em pessoa muito magra.<br>• DOAC e alguns antimicrobianos foram validados com <b>Cockcroft-Gault</b> — nesses, seguir o critério da bula.", "tag": "Renal"}, {"f": "Creatinina subiu 0,3 mg/dL. Quais fármacos LESAM o rim e quais só \"sobem a creatinina\" sem lesar?", "v": "• <b>Nefrotóxicos reais</b>: AINE, aminoglicosídeo, <b>vancomicina (pior com piperacilina-tazobactam)</b>, anfotericina B, contraste iodado, colistina, tenofovir, cisplatina.<br>• <b>Tríplice ameaça</b>: <b>IECA/BRA + diurético + AINE</b>.<br>• <b>Sobem a creatinina SEM lesão</b> (bloqueiam a secreção tubular): <b>trimetoprima, cimetidina, cobicistate, dolutegravir</b> — ureia e TFG real permanecem normais.", "tag": "Renal"}, {"f": "Ureia 90 e creatinina 1,1: o que essa dissociação sugere e o que o farmacêutico revisa?", "v": "• <b>Relação ureia/creatinina desproporcional</b> (ureia/Cr &gt;40 em mg/dL ou BUN/Cr &gt;20) = padrão <b>pré-renal</b>: desidratação, hipovolemia, ICC, diurético em excesso.<br>• Também sobe em <b>hemorragia digestiva</b>, dieta hiperproteica e <b>corticoide</b> (catabolismo).<br>• Conduta: repor volume, <b>suspender/reduzir diurético, IECA/BRA e AINE</b> e reavaliar antes de assumir lesão renal intrínseca.", "tag": "Renal"}, {"f": "Diabético com creatinina normal: qual exame urinário detecta lesão renal precoce e o que fazer com o resultado?", "v": "• <b>Relação albumina/creatinina urinária (RAC) em amostra isolada</b> — a fita do EAS só detecta proteinúria acima de ~300 mg/dia (tarde demais).<br>• KDIGO: <b>A1 &lt;30; A2 30-300 (microalbuminúria); A3 &gt;300 mg/g</b>. Confirmar em 2 de 3 amostras (exercício, febre, ITU e ICC dão falso-positivo).<br>• A partir de A2: <b>IECA/BRA + iSGLT2</b>, controle de PA e glicemia — a albuminúria é alvo terapêutico, não só marcador.", "tag": "Renal"}, {"f": "EAS: o que cada cilindro sugere e quando NÃO tratar bacteriúria?", "v": "• <b>Cilindros granulosos pigmentares</b> = necrose tubular aguda; <b>hemáticos</b> = glomerulonefrite; <b>leucocitários</b> = pielonefrite ou <b>nefrite intersticial por fármaco</b>; hialinos = inespecífico/desidratação.<br>• <b>ITU</b>: nitrito positivo é específico (enterobactérias), esterase leucocitária é sensível; diagnóstico exige <b>sintoma</b>.<br>• <b>Bacteriúria assintomática não se trata</b> — exceto <b>gestante</b> e pré-procedimento urológico invasivo.", "tag": "Renal"}, {"f": "Como classificar rapidamente lesão hepática em HEPATOCELULAR x COLESTÁTICA?", "v": "• Calcular o <b>valor R = (TGP/LSN) ÷ (FA/LSN)</b>.<br>• <b>R ≥5 = hepatocelular</b> (predomina TGO/TGP): paracetamol, isoniazida, metotrexato, estatina, nevirapina.<br>• <b>R ≤2 = colestático</b> (predomina FA/GGT/BD): amoxicilina-clavulanato, azitromicina, estrógeno, anabolizante, clorpromazina.<br>• <b>R entre 2 e 5 = misto</b> (sulfa, fenitoína, carbamazepina).", "tag": "Hepático"}, {"f": "FA alta com GGT normal x FA alta com GGT alta: qual a leitura?", "v": "• <b>FA alta + GGT alta</b> = origem <b>hepatobiliar/colestase</b> (a GGT confirma a procedência).<br>• <b>FA alta + GGT normal</b> = origem <b>óssea</b> (doença de Paget, metástase, crescimento), gestação ou intestino.<br>• <b>GGT isolada alta</b>, sem outra alteração: <b>álcool</b> ou <b>indução enzimática</b> (fenitoína, carbamazepina, fenobarbital, rifampicina) — não indica lesão nem exige suspender o fármaco.", "tag": "Hepático"}, {"f": "Icterícia: bilirrubina INDIRETA alta x DIRETA alta — qual mecanismo e quais fármacos entram na conta?", "v": "• <b>Indireta (não conjugada)</b>: excesso de produção ou falha de conjugação — <b>hemólise</b>, síndrome de Gilbert, hematoma; fármacos: <b>atazanavir, indinavir, rifampicina</b> (inibem UGT1A1/captação — icterícia benigna, sem lesão).<br>• <b>Direta (conjugada) &gt;50%</b>: colestase ou lesão hepatocelular — obstrução biliar, DILI, sepse.<br>Macete: <b>indireta = problema ANTES do hepatócito; direta = problema NO ou DEPOIS dele</b>.", "tag": "Hepático"}, {"f": "Quais dois exames medem FUNÇÃO DE SÍNTESE hepática, e qual sinaliza gravidade aguda?", "v": "• <b>Albumina</b> (meia-vida ~20 dias) = comprometimento <b>crônico</b>; cai também em desnutrição, síndrome nefrótica e inflamação.<br>• <b>INR/TP</b> (fator VII, meia-vida 4-6 h) = comprometimento <b>agudo</b> — sobe primeiro e é o marcador de gravidade (ambos entram no Child-Pugh).<br>• <b>Lei de Hy</b>: TGP ≥3× LSN + bilirrubina total ≥2× LSN sem colestase = <b>DILI grave</b> (~10% de óbito/transplante) → suspender o fármaco imediatamente.", "tag": "Hepático"}, {"f": "Potássio 6,2 mEq/L. Quais fármacos você revisa e qual causa \"falsa\" precisa excluir?", "v": "• <b>Pseudo-hipercalemia</b>: hemólise da amostra, garrote prolongado, punção difícil, leucocitose/plaquetose extremas → <b>repetir a coleta</b> antes de intervir.<br>• Fármacos: <b>IECA/BRA, espironolactona/amilorida, sacubitril-valsartana, sulfametoxazol-trimetoprima, heparina, AINE, betabloqueador, ciclosporina/tacrolimo, suplemento de KCl</b>.<br>• &gt;6,5 ou alteração no ECG: <b>gluconato de cálcio</b> (protege o miocárdio) + insulina/glicose e beta-2 (deslocam) + resina/diurético/diálise (retiram).", "tag": "Eletrólitos"}, {"f": "Hipocalemia que não corrige com KCl: o que faltou dosar? E quais fármacos causam?", "v": "• Faltou o <b>magnésio</b>: hipomagnesemia perpetua a perda renal de potássio (e refratariza também a hipocalcemia) — <b>corrigir o Mg primeiro</b>.<br>• Fármacos que espoliam K: <b>diurético de alça e tiazídico, anfotericina B, corticoide, beta-2 agonista, insulina, laxante, aminoglicosídeo</b>. Espoliam Mg: <b>IBP crônico, alça, anfotericina B, cisplatina</b>.<br>• Risco maior com <b>digoxina</b> (potencializa a toxicidade) e com fármacos que alargam QT.", "tag": "Eletrólitos"}, {"f": "Sódio 118 mEq/L. Quais fármacos suspeitar e qual é o limite de velocidade da correção?", "v": "• <b>SIADH medicamentoso</b>: ISRS/venlafaxina, <b>carbamazepina/oxcarbazepina</b>, antipsicóticos, ciclofosfamida, desmopressina, opioide.<br>• <b>Perda renal</b>: <b>tiazídico</b> (clássico em idosa) — a alça causa menos.<br>• Corrigir no máximo <b>8-10 mEq/L em 24 h</b> (6-8 se desnutrido, alcoolista, hipocalêmico) sob risco de <b>síndrome de desmielinização osmótica</b>. Correção rápida só na convulsão, com salina 3% em bolus.", "tag": "Eletrólitos"}, {"f": "Cálcio total 7,6 mg/dL com albumina 2,4 g/dL: o paciente está mesmo hipocalcêmico?", "v": "• Não necessariamente — <b>~45% do cálcio circula ligado à albumina</b>.<br>• <b>Ca corrigido = Ca total + 0,8 × (4 − albumina)</b> → 7,6 + 0,8 × 1,6 = <b>8,9 mg/dL (normal)</b>.<br>• Na dúvida (sepse, distúrbio ácido-base, pós-transfusão maciça), dosar o <b>cálcio iônico</b>, que é o fisiologicamente ativo. <b>Alcalose aumenta a ligação e reduz o iônico</b> — daí a tetania na hiperventilação.", "tag": "Eletrólitos"}, {"f": "Iniciou IECA/BRA ou espironolactona: quando repetir exames e qual alta de creatinina é tolerável?", "v": "• Dosar <b>potássio e creatinina em 1 a 2 semanas</b> após início ou aumento de dose (e após qualquer intercorrência com desidratação).<br>• <b>Aumento de creatinina até 30%</b> é esperado (hemodinâmico) e <b>não obriga a suspender</b> — reavaliar em 2-4 semanas. Acima disso, investigar estenose de artéria renal/hipovolemia.<br>• <b>Suspender/reduzir se K &gt;5,5 mEq/L</b>; revisar sal de potássio, AINE e SMX-TMP concomitantes.", "tag": "Eletrólitos"}, {"f": "O que exatamente a HbA1c reflete, e qual peso tem o mês mais recente?", "v": "• Reflete a <b>glicemia média dos últimos 2 a 3 meses</b> (vida da hemácia ~120 dias).<br>• Os <b>últimos 30 dias respondem por ~50%</b> do valor; os 60-120 dias anteriores por ~25% → mudança recente de tratamento já aparece parcialmente.<br>• <b>Não repetir antes de 3 meses</b> para avaliar resposta terapêutica (na gestação/instabilidade, usar glicemia ou monitorização contínua).", "tag": "Glicemia"}, {"f": "Em quais situações a HbA1c MENTE, e o que usar no lugar?", "v": "• <b>Falsamente BAIXA</b> (hemácia jovem/vida curta): <b>hemólise</b>, sangramento agudo, transfusão, gestação, esplenomegalia, reposição recente de ferro/B12 ou EPO.<br>• <b>Falsamente ALTA</b>: <b>ferropriva não tratada</b>, deficiência de B12/folato, esplenectomia, uremia, alcoolismo.<br>• <b>Hemoglobinopatia (HbS, HbC, HbF)</b>: resultado depende do método → usar <b>frutosamina, glicemias capilares ou CGM</b>.", "tag": "Glicemia"}, {"f": "Meta de HbA1c: quando afrouxar? E quais fármacos sabotam a glicemia?", "v": "• Geral: <b>&lt;7%</b>; mais rígida (&lt;6,5%) em jovem, recém-diagnosticado, sem hipoglicemia.<br>• <b>Afrouxar para 7,5-8,5%</b> em idoso frágil, expectativa de vida curta, hipoglicemias graves/despercebidas, DRC avançada, comorbidade múltipla.<br>• <b>Hiperglicemiantes</b>: corticoide, tiazídico, tacrolimo/ciclosporina, antipsicótico atípico (olanzapina/clozapina), quinolona, inibidor de protease, niacina, beta-bloqueador (mascara hipoglicemia).", "tag": "Glicemia"}, {"f": "Gasometria: descreva o passo a passo para classificar o distúrbio ácido-base.", "v": "1) <b>pH</b>: &lt;7,35 acidemia, &gt;7,45 alcalemia. 2) Ver <b>pCO2 (35-45)</b> e <b>HCO3 (22-26)</b> e achar o culpado.<br>3) Mnemônico <b>ROME</b>: <b>R</b>espiratório = <b>O</b>posto (pH e pCO2 em direções contrárias); <b>M</b>etabólico = <b>E</b>quivalente (pH e HCO3 na mesma direção).<br>4) Calcular o <b>ânion gap</b> em toda acidose metabólica. 5) Checar a <b>compensação</b> — se não bate, há distúrbio misto.", "tag": "Gasometria"}, {"f": "Acidose metabólica com HCO3 12: como saber se a compensação respiratória é adequada?", "v": "• <b>Fórmula de Winter: pCO2 esperada = 1,5 × HCO3 + 8 (±2)</b> → aqui 26 ± 2.<br>• <b>pCO2 medida MAIOR</b> que o esperado = <b>acidose respiratória associada</b> (o paciente está cansando — sinal de gravidade).<br>• <b>pCO2 MENOR</b> = alcalose respiratória associada (sepse, salicilato, dor).<br>• Regra: <b>a compensação nunca normaliza o pH nem \"ultrapassa\" o distúrbio primário</b>.", "tag": "Gasometria"}, {"f": "Ânion gap: como calcular, como corrigir pela albumina e quais fármacos o elevam?", "v": "• <b>AG = Na − (Cl + HCO3)</b>; normal <b>8-12 mEq/L</b>. <b>Corrigir: +2,5 para cada 1 g/dL de albumina abaixo de 4</b> (hipoalbuminemia mascara AG alto).<br>• <b>AG alto</b> (mnemônico <b>MUDPILES</b>): metanol, uremia, cetoacidose diabética, propilenoglicol/propofol, isoniazida/ferro, <b>acidose láctica (metformina, linezolida)</b>, etilenoglicol, salicilato.<br>• <b>AG normal (hiperclorêmica)</b>: diarreia, acetazolamida, salina 0,9% em excesso, acidose tubular renal.", "tag": "Gasometria"}, {"f": "Metformina: quais dois exames o farmacêutico monitora e com que gatilhos?", "v": "• <b>Função renal (TFG)</b>: TFG ≥45 uso pleno; <b>30-45 não iniciar</b> e reduzir a dose (máx ~1000 mg/dia); <b>&lt;30 contraindicada</b> (risco de acidose láctica). Suspender em contraste iodado se TFG &lt;30 e em doença aguda com hipoperfusão.<br>• <b>Vitamina B12</b>: má absorção dose/tempo-dependente — dosar <b>anualmente</b> após uso prolongado ou se houver <b>anemia macrocítica ou neuropatia</b> (que pode ser confundida com neuropatia diabética).", "tag": "Monitorização"}, {"f": "Ligue o fármaco ao exame de segurança obrigatório: clozapina, lítio, amiodarona.", "v": "• <b>Clozapina → neutrófilos (ANC)</b>: semanal por 18 semanas, depois mensal; <b>interromper se ANC &lt;1500</b>, suspensão definitiva se &lt;1000 (agranulocitose).<br>• <b>Lítio → litemia + TSH + creatinina</b>: litemia <b>12 h após a dose</b> (alvo 0,6-1,2 mEq/L); TSH e função renal a cada 6 meses. Sobem a litemia: <b>tiazídico, IECA/BRA, AINE</b>.<br>• <b>Amiodarona → TSH/T4L e TGO/TGP a cada 6 meses</b> + RX de tórax anual e avaliação oftalmológica (meia-vida ~50 dias).", "tag": "Monitorização"}, {"f": "Metotrexato semanal: que tripé laboratorial monitorar e quais interações são proibidas?", "v": "• <b>Hemograma + TGO/TGP/albumina + creatinina</b>: a cada 2-4 semanas nos 3 primeiros meses, depois a cada 3 meses.<br>• Suspender se <b>TGP &gt;3× LSN</b>, citopenia ou queda da TFG — o MTX é <b>excretado por via renal</b> e acumula.<br>• Evitar: <b>sulfametoxazol-trimetoprima</b> (dupla antifólico → pancitopenia), AINE em dose alta, probenecida, IBP em altas doses.<br>• Sempre associar <b>ácido fólico</b> em dia diferente do MTX.", "tag": "Monitorização"}, {"f": "Paciente em estatina com mialgia: você pede CK de rotina? Quando suspender?", "v": "• <b>CK não é exame de rotina</b> — dosar <b>basal</b> em quem tem risco (idoso, DRC, hipotireoidismo, interação) e <b>sempre que houver sintoma muscular</b>.<br>• <b>Suspender se CK &gt;10× LSN</b> ou se houver rabdomiólise (mioglobinúria, alta de creatinina).<br>• <b>TGP basal</b>; não repetir de rotina — suspender apenas se &gt;3× LSN persistente.<br>• Antes de culpar a estatina: checar <b>TSH</b> e interações (genfibrozila, claritromicina, amiodarona, ciclosporina).", "tag": "Monitorização"}, {"f": "Quando o LDL do laudo é CALCULADO e não pode ser usado? Precisa de jejum?", "v": "• Friedewald: <b>LDL = CT − HDL − (TG/5)</b>; torna-se <b>inválido com triglicerídeos &gt;400 mg/dL</b> (subestima o LDL) → pedir <b>LDL direto</b> ou usar o <b>não-HDL (CT − HDL)</b>.<br>• <b>Jejum não é obrigatório</b> para o perfil lipídico de rotina (diretriz brasileira): manter jejum de 12 h quando TG &gt;440 ou para avaliar hipertrigliceridemia.<br>• Reavaliar o lipidograma <b>4 a 12 semanas</b> após iniciar ou ajustar a estatina.", "tag": "Monitorização"}, {"f": "Fenitoína 18 mcg/mL em paciente com albumina 2,0: nível tóxico ou subterapêutico?", "v": "• Fenitoína é <b>~90% ligada à albumina</b>; na hipoalbuminemia a fração LIVRE (ativa) sobe e o nível total engana.<br>• <b>Sheiner-Tozer: C corrigida = C medida ÷ [(0,2 × albumina) + 0,1]</b> → 18 ÷ 0,5 = <b>36 mcg/mL = tóxico</b> (faixa 10-20). Em TFG &lt;20, trocar 0,2 por 0,1.<br>• Outros: <b>carbamazepina</b> (hiponatremia, leucopenia, autoindução) e <b>valproato</b> (plaquetopenia, amônia alta, hepatotoxicidade).", "tag": "Monitorização"}, {"f": "Plaquetas caíram 60% no 7º dia de heparina. Qual a hipótese e qual o ERRO clássico de conduta?", "v": "• <b>HIT (trombocitopenia induzida por heparina)</b>: queda &gt;50% entre o <b>5º e o 10º dia</b>, avaliada pelo escore <b>4Ts</b>; é um quadro <b>PRÓ-trombótico</b>, apesar da plaquetopenia.<br>• Erro clássico: <b>apenas suspender a heparina</b> ou <b>transfundir plaquetas</b>.<br>• Correto: suspender <b>toda</b> heparina (inclusive flush e HBPM) e iniciar <b>anticoagulante não heparínico</b> (argatrobana, fondaparinux); só passar a varfarina depois da recuperação das plaquetas.", "tag": "Monitorização"}, {"f": "Troponina alta = infarto? E qual pegadinha do BNP em quem usa sacubitril-valsartana?", "v": "• <b>Não</b>: importa a <b>variação (delta) em 0/1 h ou 0/3 h</b> + clínica. Troponina cronicamente elevada ocorre em <b>DRC, IC, FA, sepse, TEP, miocardite</b>.<br>• <b>BNP/NT-proBNP</b> têm <b>alto VPN</b> para excluir IC aguda (NT-proBNP &lt;300 pg/mL). <b>Obesidade reduz</b>; idade, FA e DRC elevam.<br>• <b>Sacubitril inibe a neprilisina → o BNP SOBE artificialmente</b>; nesses pacientes acompanhar pelo <b>NT-proBNP</b>, que não é degradado pela neprilisina.", "tag": "Monitorização"}, {"f": "PCR, VHS e procalcitonina: qual serve para DECIDIR suspender o antimicrobiano?", "v": "• <b>Procalcitonina</b>: mais específica para <b>infecção bacteriana</b> (não sobe em virose nem em inflamação estéril). Sugere <b>suspender/descalonar o ATB</b> quando <b>&lt;0,25-0,5 ng/mL</b> ou com <b>queda ≥80% do pico</b> — sempre junto da clínica.<br>• <b>PCR</b>: sobe em 6-8 h, meia-vida ~19 h → boa para acompanhar a <b>tendência</b> diária.<br>• <b>VHS</b>: lento para subir e para cair (semanas) — útil em doença crônica/inflamatória, inútil para decisão aguda.", "tag": "Monitorização"}, {"f": "Fase pré-analítica: cite os erros que invalidam o exame e o horário certo de coleta na monitorização terapêutica.", "v": "• <b>Hemólise</b>: eleva falsamente <b>potássio, LDH, AST, magnésio e fósforo</b> — resultado deve ser recoletado, não tratado.<br>• <b>Garrote &gt;1 minuto</b>: hemoconcentra (sobe cálcio, proteínas, potássio). Glicose cai ~7%/h sem tubo com fluoreto.<br>• <b>Vale (imediatamente antes da próxima dose)</b>: vancomicina, fenitoína, ciclosporina, tacrolimo — colher no <b>estado de equilíbrio</b>.<br>• Exceções: <b>litemia 12 h após a dose</b> e <b>digoxina ≥6-8 h após a dose</b> (fase de distribuição).", "tag": "Monitorização"}]}];
